import "server-only";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { planIntroMonthlyCents, planIntroTermMonths } from "@/lib/intro-pricing";
import { annualDiscountPct } from "@/lib/annual-discount";
import { VPS_TERMS, termDiscountPct } from "@/lib/billing-terms";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { CUSTOMER_REGION_LABELS } from "@/lib/node-regions";

/**
 * Real catalogue data for the new marketing pages — the same tables, pricing
 * helpers and deploy-link contract the live site, the deploy wizard and
 * checkout use. Nothing here is a snapshot: every page loader reads these at
 * request time.
 *
 * Prices are USD (the charge currency), formatted the way the design shows
 * them ("$12.78").
 */

export const usd = (cents: number) => `$${(cents / 100).toFixed(2)}`;
export const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const gb = (mb: number) => Math.round((mb / 1024) * 10) / 10;

/** "first month" / "first 3 months" / "first term" for an intro rate. */
export function introSpan(months: number | null) {
  if (months == null) return "first term";
  return months === 1 ? "first month" : `first ${months} months`;
}

// ── VPS ────────────────────────────────────────────────────────────────────
export type VpsPlan = {
  id: string; slug: string; n: string; cpu: number; ram: number; disk: number; bw: number;
  /** regular monthly price, dollars (the design's `p`) */ p: number;
  /** intro monthly price, dollars, or null (the design's `i`) */ i: number | null;
  /** months the intro rate lasts (null = whole first term) */ it: number | null;
  href: string;
};

export async function vpsPlans(region?: string): Promise<VpsPlan[]> {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  return plans.map((p) => {
    const intro = planIntroMonthlyCents(p);
    return {
      id: p.id, slug: p.slug, n: p.name, cpu: p.cpuCores, ram: gb(p.ramMB), disk: p.diskGB, bw: p.bandwidthTB,
      p: p.priceCents / 100, i: intro == null ? null : intro / 100, it: intro == null ? null : planIntroTermMonths(p),
      href: deployHref({ service: "vps", planId: p.id, termMonths: 1, region }),
    };
  });
}

/** The design's TERM map ({0: 0, 12: .2, 24: .3, 36: .4}) from the real terms. */
export async function vpsTermMap(): Promise<Record<number, number>> {
  const annual = await annualDiscountPct();
  const out: Record<number, number> = {};
  for (const t of VPS_TERMS) out[t.months === 1 ? 0 : t.months] = termDiscountPct(t.months, annual) / 100;
  return out;
}

export async function diskPerGb() {
  return usd(await extraDiskPerGbCents());
}

// ── Game servers ───────────────────────────────────────────────────────────
export type GameTier = {
  id: string; family: string; name: string; ram: number; cpu: number; disk: number; slots: number | null;
  p: number; i: number | null; it: number | null; href: string;
};

export async function gameTiers(family?: string, region?: string): Promise<GameTier[]> {
  const rows = await db.gamePlan.findMany({
    where: { active: true, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ ramMB: "asc" }, { sortOrder: "asc" }],
  });
  return rows.map((g) => {
    const perMonth = (c: number) => (g.termMonths > 1 ? c / g.termMonths : c);
    const intro = planIntroMonthlyCents(g);
    return {
      id: g.id, family: g.gameFamily, name: g.name, ram: gb(g.ramMB), cpu: g.cpuCores, disk: g.diskGB, slots: g.slots,
      p: perMonth(g.priceCents) / 100, i: intro == null ? null : perMonth(intro) / 100,
      it: intro == null ? null : planIntroTermMonths(g),
      href: deployHref({ service: "game", gameFamily: g.gameFamily, gamePlanId: g.id, region }),
    };
  });
}

export function gameName(family: string) {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

// ── Regions ────────────────────────────────────────────────────────────────
/** Regions with an enabled node — what a customer can actually deploy into. */
export async function liveRegions() {
  const nodes = await db.node.findMany({ where: { enabled: true }, select: { region: true } });
  const codes = [...new Set(nodes.map((n) => n.region))];
  return codes.map((code) => ({ code, label: CUSTOMER_REGION_LABELS[code as keyof typeof CUSTOMER_REGION_LABELS] ?? code }));
}

// ── Structured data (same shapes as components/marketing/StructuredData) ──
import { APP_URL } from "@/components/marketing/StructuredData";

/** Product + AggregateOffer from real plans (price in dollars). */
export function productLd(name: string, description: string, route: string, offers: { name: string; price: number }[]) {
  const priced = offers.filter((o) => Number.isFinite(o.price) && o.price > 0);
  return {
    "@context": "https://schema.org", "@type": "Product", name, description,
    brand: { "@type": "Brand", name: "Nxeon" },
    offers: {
      "@type": "AggregateOffer", priceCurrency: "USD",
      lowPrice: priced.length ? Math.min(...priced.map((o) => o.price)).toFixed(2) : undefined,
      offerCount: priced.length,
      offers: priced.map((o) => ({
        "@type": "Offer", name: o.name, price: o.price.toFixed(2), priceCurrency: "USD",
        availability: "https://schema.org/InStock", url: APP_URL + route,
      })),
    },
  };
}

/** What a page loader returns (see NxmPage): markup slots, data for the page
 *  script, and extra JSON-LD. */
export type NxmLoad = { slots?: Record<string, string>; data?: unknown; jsonLd?: object[]; crumb?: string };
import "server-only";
import { introSpan, productLd, usd, vpsPlans } from "./lib";

/** The design's "Great for" line per plan — copy, keyed by the real plan slug. */
const GREAT_FOR: Record<string, string> = {
  starter: "Personal sites, dev and staging, bots, VPNs",
  standard: "WordPress, WooCommerce, small game servers, CI runners",
  pro: "Busy sites, databases, Docker stacks",
  max: "High-traffic apps, big databases, heavy workloads",
};

/** /free-vps — the plans a customer keeps after a free start, all real. */
export async function load(_p: Record<string, string>) {
  const vps = await vpsPlans();
  if (!vps.length) throw new Error("nxm free-vps: no active VPS plans");
  const cheapest = vps.reduce((a, b) => ((a.i ?? a.p) <= (b.i ?? b.p) ? a : b));
  const startSentence = cheapest.i != null
    ? `${usd(Math.round(cheapest.i * 100))} for the ${introSpan(cheapest.it)} on the ${cheapest.n} plan, then ${usd(Math.round(cheapest.p * 100))} a month`
    : `${usd(Math.round(cheapest.p * 100))} a month on the ${cheapest.n} plan`;
  return {
    data: {
      pl: vps.map((p) => ({ n: p.n, i: p.i, r: p.p, is: introSpan(p.it), cpu: p.cpu, ram: p.ram, disk: p.disk, bw: p.bw,
        g: GREAT_FOR[p.slug] ?? "", pop: p.slug === "standard" ? 1 : 0, href: p.href })),
      // the "keep a server" timeline demo, on the cheapest real plan
      keep: {
        first: cheapest.i ?? cheapest.p,
        firstLabel: cheapest.i != null ? `${usd(Math.round(cheapest.i * 100))} ${introSpan(cheapest.it)}` : `${usd(Math.round(cheapest.p * 100))} a month`,
        regularLabel: usd(Math.round(cheapest.p * 100)),
        note: `${cheapest.n}: ${startSentence}. Cancel or resize any time.`,
      },
    },
    slots: { "vps.startSentence": startSentence },
    jsonLd: [productLd("Nxeon Cloud VPS", "Start free with no card; servers you keep are NVMe cloud VPS with full root and DDoS protection.",
      "/free-vps", vps.map((p) => ({ name: `${p.n} VPS`, price: p.i ?? p.p })))],
  };
}
/** Route params + fixed template params + the query string, as one flat map for
 *  a page loader. Query values arrive under their own names (first value). */
export async function nxmParams(
  params: Promise<Record<string, string>>,
  searchParams: Promise<Record<string, string | string[] | undefined>>,
  fixed: Record<string, string>,
): Promise<Record<string, string>> {
  const [pr, sp] = await Promise.all([params, searchParams]);
  const q: Record<string, string> = {};
  for (const [k, v] of Object.entries(sp ?? {})) {
    const first = Array.isArray(v) ? v[0] : v;
    if (typeof first === "string") q[k] = first;
  }
  return { ...q, ...(pr ?? {}), ...fixed };
}

