137	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
138	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
139	  if (modIds.length === 0) return new Map();
140	  const rows = await db.modRating.groupBy({
141	    by: ["gameModId"],
142	    where: { gameModId: { in: modIds } },
143	    _avg: { rating: true },
144	    _count: { rating: true },
145	  });
146	  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
147	}
