225	/**
226	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
227	 * the one honest exception: avgRating is computed from a separate ModRating
228	 * table with no cached column on GameMod, and Prisma's relation-aggregate
229	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
230	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
231	 * and re-sorting by rating WITHIN each page (below) is a documented
232	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
233	 * re-ordered by rating, not the true 25th-48th highest-rated mods
234	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
235	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
236	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
237	 * the rating mutation) and give this its own real orderBy.
238	 */
239	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
240	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
241	  downloads: [{ downloads: "desc" }, { name: "asc" }],
242	  latest: [{ createdAt: "desc" }],
243	  rating: [{ downloads: "desc" }, { name: "asc" }],
244	};
245	
246	/**
247	 * Real, server-side, paginated + searched + sorted catalogue query — the
248	 * single data source behind every StoreBrowser instance (marketing and
249	 * portal, cross-game and per-family). Replaces the old
250	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
251	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
252	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
253	 * capping the catalogue at families with thousands+ of real imported rows.
254	 */
255	export async function queryCatalogMods(opts: {
256	  family?: string;
257	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
258	  category?: string;
259	  q?: string;
260	  sort?: CatalogSort;
261	  page?: number;
262	  perPage?: number;
263	}): Promise<CatalogPage> {
264	  const sort = opts.sort ?? "featured";
265	  const q = (opts.q ?? "").trim();
266	  const where: Prisma.GameModWhereInput = {
267	    active: true,
268	    upstreamOk: true,
269	    ...(opts.family ? { gameFamily: opts.family } : {}),
270	    ...(opts.category ? { category: opts.category } : {}),
271	    ...(q
272	      ? {
273	          OR: [
274	            { name: { contains: q, mode: "insensitive" } },
275	            { category: { contains: q, mode: "insensitive" } },
276	            { description: { contains: q, mode: "insensitive" } },
277	          ],
278	        }
279	      : {}),
280	  };
281	
282	  const total = await db.gameMod.count({ where });
283	  const { skip, take, page, pages, perPage } = paginate(
284	    { page: opts.page != null ? String(opts.page) : undefined },
285	    total,
286	    opts.perPage ?? CATALOG_PAGE_SIZE
287	  );
288	
289	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
290	  const aggs = await ratingAggs(rows.map((r) => r.id));
291	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
292	  if (sort === "rating") {
293	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
294	  }
295	
296	  return { mods, total, page, totalPages: pages, perPage };
297	}
