299	/**
300	 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
301	 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
302	 * sorts by first), never a synthetic pick. Ordered by real downloads within
303	 * the featured set so the best-known featured mod leads. Returns fewer than
304	 * `take` (down to zero) when a family simply hasn't had any mods marked
305	 * featured yet — callers render nothing rather than pad with non-featured
306	 * rows, matching this file's no-guessing rule. Omit `family` for a
307	 * cross-game rail (the NxLabs homepage's curated "Featured" row, item 6 of
308	 * the 2026-09-20 overhaul), same optional-family convention as
309	 * listTopDownloadedMods/listRecentlyUpdatedMods below.
310	 */
311	export async function listFeaturedMods(family?: string, take = 8): Promise<ModSummary[]> {
312	  const rows = await db.gameMod.findMany({
313	    where: { active: true, upstreamOk: true, featured: true, ...(family ? { gameFamily: family } : {}) },
314	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
315	    take,
316	  });
317	  const aggs = await ratingAggs(rows.map((r) => r.id));
318	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
319	}
