321	/**
322	 * Curated "Most downloaded" rail — real `GameMod.downloads`, DB-side sorted
323	 * and DB-side filtered to `downloads: { not: null }`. That filter matters:
324	 * Postgres' default NULLS FIRST for a DESC sort would otherwise put every
325	 * never-verified (downloads: null) row ahead of real numbers — see the
326	 * `rust`/`cs2` families, which currently have zero mods with a real
327	 * `downloads` count and so correctly return an empty array here rather than
328	 * a page of nulls masquerading as "most downloaded". Omit `family` for a
329	 * cross-game rail (the NxLabs homepage's curated section).
330	 */
331	export async function listTopDownloadedMods(family?: string, take = 8): Promise<ModSummary[]> {
332	  const rows = await db.gameMod.findMany({
333	    where: { active: true, upstreamOk: true, downloads: { not: null }, ...(family ? { gameFamily: family } : {}) },
334	    orderBy: [{ downloads: "desc" }, { name: "asc" }],
