467	    row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
468	  }
469	  if (!row || !row.active) return null;
470	  const aggs = await ratingAggs([row.id]);
471	  return toDetail(row, aggs.get(row.id));
