530	/**
531	 * `id` is the real, live `GamePlan.id` this recommendation resolved to — kept
532	 * on the result (not just derived data) so a caller can hand it straight to
533	 * `deployHref({ gamePlanId })` and land the wizard on this EXACT plan, the
534	 * same real-tier resolution `order.tsx`'s `orderFromIntent` already does for
535	 * a `tier` query param. Never a synthetic id — always one of the
536	 * `gamePlans` rows passed in below.
537	 */
538	export type RecommendedPlan = { id: string; planName: string; ramMB: number; priceCents: number } | null;
