540	/**
541	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
542	 * light-impact mods run on any active plan for the family; moderate needs at
543	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
544	 * for the family that clears the bar, or null if none does (never guesses a
545	 * number that isn't a real, active, orderable plan). `null` is also the
546	 * honest signal for a family with zero active GamePlan rows at all (e.g.
547	 * "schedule1", which has no official dedicated server and stays unseeded —
548	 * see lib/games.ts) — callers must not render a deploy action in that case.
549	 */
550	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "id" | "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
551	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
552	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
553	  const pick = candidates[0];
554	  return pick ? { id: pick.id, planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
555	}
