571	/**
572	 * An honest, field-derived description for the small slice of active mods
573	 * with neither a real `description` tagline nor a `longDescription` body —
574	 * confirmed live 2026-09-20 (NxLabs overhaul, item 4): 148 of 45,766 active
575	 * mods (0.3%; mostly minimal Steam Workshop skin/map submissions and a
576	 * couple of GitHub repos with a blank `description` field) have nothing at
577	 * all from their source. This is composed only from real columns already on
578	 * the row — category, game, loader/variant, a game version, file size —
579	 * never invented marketing copy. `mod.description` and `mod.longDescription`
580	 * both being empty is the ONLY case that should ever reach this; callers
581	 * must prefer the real fields first.
582	 *
583	 * Separately: the much larger gap — 94.9% of active mods (all 32,243
584	 * Modrinth rows) have a real `description` tagline but no `longDescription`
585	 * — is NOT what this function is for. That gap exists because
586	 * scripts/backfill-modrinth-descriptions.ts, which fetches Modrinth's real
587	 * project `body` and is fully idempotent/rate-limited, has only ever been
588	 * run as a dry run against production, never with `--apply`. That is a
589	 * one-time data-backfill run to do, not a rendering fallback — see this
590	 * task's final report.
591	 */
592	export function composedDescriptionFor(
593	  mod: Pick<ModDetail, "category" | "gameFamilyLabel" | "loaders" | "appliesToVariant" | "gameVersions" | "fileBytes">
594	): string {
595	  const bits = [`A ${mod.category} for ${mod.gameFamilyLabel}`];
596	  const platform = mod.loaders[0] ?? mod.appliesToVariant;
597	  if (platform) bits.push(platform);
598	  const version = mod.gameVersions[mod.gameVersions.length - 1];
599	  if (version) bits.push(`version ${version}`);
600	  let text = `${bits.join(", ")}.`;
601	  const size = formatBytes(mod.fileBytes);
602	  if (size) text += ` ${size} download.`;
603	  return text;
604	}
