613	export type ResolvedDownload = { url: string; direct: boolean } | null;
614	
615	/**
616	 * The synchronous half of download resolution — every source EXCEPT
617	 * modrinth/thunderstore resolves with no network call at all (spigotmc's
618	 * Spiget endpoint is a constructed URL, everything else is just `mod.url`).
619	 * Returns `undefined` for modrinth/thunderstore specifically, meaning "a
620	 * live external API call is required" — callers that can't afford to block
621	 * on that (see StoreBrowser.tsx) use this to render immediately for the
622	 * ~50% of the catalogue that needs no network at all, and defer the rest to
623	 * an on-demand client resolve.
624	 *
625	 * REAL PERFORMANCE FIX (2026-09-21): `resolveDownloadUrl` below used to be
626	 * called via `Promise.all` for EVERY mod card in StoreBrowser's grid (up to
627	 * `CATALOG_PAGE_SIZE`=24 per /mods and /dashboard/nxlabs page load). That was
628	 * a real, harmless-looking pattern when the catalogue was ~124 hand-seeded
629	 * rows with few resolvable `sourceId`s; the moment the Modrinth bulk import
630	 * landed 32,000+ real rows, most default/browse pages became Modrinth-
631	 * dominated, and every single page load started firing up to 24 concurrent,
632	 * uncached, un-timed-out HTTPS calls to api.modrinth.com as part of server
633	 * rendering — measured live against production at 1-2.2s of REAL added
634	 * latency per page load (see docs/DOCUMENTATION.md's 2026-09-21 entry for
635	 * the exact numbers), with no upper bound if Modrinth itself is ever slow.
636	 * Splitting the sync-resolvable 50%+ of sources out, and deferring the
637	 * network-bound rest to a click-triggered resolve (DownloadButton.tsx +
638	 * lib/actions-mods.ts's resolveModDownloadAction), removes ALL of that from
639	 * the server-render critical path — a card the visitor never clicks now
640	 * costs zero external requests, instead of one whether it's clicked or not.
641	 */
642	export function resolveDownloadUrlSync(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): ResolvedDownload | undefined {
643	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
644	  const id = mod.sourceId ?? "";
645	  if (!id) return fallback;
646	  if (mod.source === "modrinth" || mod.source === "thunderstore") return undefined;
647	  if (mod.source === "spigotmc") {
648	    // Spiget's own download endpoint 302s to the real jar — genuinely direct, no fetch needed to know that.
649	    return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
650	  }
651	  return fallback;
652	}
653	
654	/**
655	 * The uncached live-fetch half of `resolveDownloadUrl` below — pulled out on
656	 * its own so `unstable_cache` (see `resolveDownloadUrlCached`) wraps ONLY the
657	 * tiny resolved `{url, direct}` result, never the raw upstream response body.
658	 *
659	 * REAL BUG FIX (2026-09-22): this used to rely on `next: { revalidate: 3600 }`
660	 * on the `fetch` calls themselves — Next's fetch data-cache, which silently
661	 * refuses to store any response over roughly 2MB and simply re-fetches live
662	 * on every call instead, with no error or warning. Confirmed live via
663	 * journalctl: `minecraft-comes-alive-reborn`'s Modrinth `/version` response is
664	 * 20,035,322 bytes, so it was being re-fetched from api.modrinth.com on
665	 * EVERY single visit to that mod's detail page with zero caching benefit —
666	 * and Modrinth's version-list responses routinely run large for mods with
667	 * many released files, so this wasn't an isolated case. The actual value we
668	 * need to cache is a couple hundred bytes (`{url, direct}`); caching that
669	 * directly via `unstable_cache` sidesteps the fetch-cache size ceiling
670	 * entirely, for every mod regardless of how large its upstream response is.
671	 */
672	async function fetchLiveDownload(source: string, sourceId: string): Promise<{ url: string; direct: boolean } | null> {
673	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
674	  try {
675	    if (source === "modrinth") {
676	      const headers: Record<string, string> = { "User-Agent": UA };
677	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
678	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, {
679	        headers,
680	        signal: AbortSignal.timeout(5000),
681	      });
682	      if (!res.ok) return null;
683	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
684	      const v = versions[0];
685	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
686	      return file ? { url: file.url, direct: true } : null;
687	    }
688	    if (source === "thunderstore") {
689	      const [namespace, ...rest] = sourceId.split("-");
690	      if (!namespace || !rest.length) return null;
691	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
692	        headers: { "User-Agent": UA },
693	        signal: AbortSignal.timeout(5000),
694	      });
695	      if (!res.ok) return null;
696	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
697	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : null;
698	    }
699	  } catch {
700	    return null;
701	  }
702	  return null;
703	}
704	
705	const fetchLiveDownloadCached = unstable_cache(fetchLiveDownload, ["mods-catalog:resolveDownloadUrl"], {
706	  revalidate: 3600,
707	});
708	
709	/**
710	 * The real, authoritative download for a mod detail page. Prefers the
711	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
712	 * install it) so a visitor gets the actual file, not just a landing page;
713	 * falls back to the mod's own project/resource page (still the real,
714	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
715	 * be resolved live or isn't one of the three we know how to resolve.
716	 *
717	 * Fine to call eagerly for ONE mod (the detail pages do exactly that) — the
718	 * cost that mattered was calling it for a whole page of cards at once, see
719	 * `resolveDownloadUrlSync` above. Every live fetch carries a 5s timeout
720	 * (`AbortSignal.timeout`) so a slow/unresponsive upstream can never hang this
721	 * past a bounded worst case — there was no timeout at all before 2026-09-21,
722	 * so a degraded Modrinth/Thunderstore response could block a caller
723	 * indefinitely. The live fetch itself is cached via `unstable_cache`, not
724	 * `next: { revalidate }` — see `fetchLiveDownload`'s comment for why.
725	 */
726	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<ResolvedDownload> {
727	  const sync = resolveDownloadUrlSync(mod);
728	  if (sync !== undefined) return sync;
729	
730	  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
731	  const id = mod.sourceId ?? "";
732	  const live = await fetchLiveDownloadCached(mod.source, id);
733	  return live ?? fallback;
734	}
