  SOURCE_LABEL,
  type ModDetail,
} from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

type Params = { params: Promise<{ family: string; slug: string }> };

export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
  return listCatalogSlugs();
}

/**
 * Real, non-fabricated images for a mod, in preference order: its own icon
 * first (the small square logo every card/detail page already leads with),
 * then its real gallery screenshots (Modrinth's project `gallery[]`).
 * Returns [] for a mod with neither — callers must omit the `image`/`images`
 * property entirely rather than pad it with a stand-in, matching this
 * catalogue's no-guessing convention (see lib/mods-catalog.ts's file header).
 */
function realImagesFor(mod: Pick<ModDetail, "iconUrl" | "galleryUrls">): string[] {
  return [mod.iconUrl, ...mod.galleryUrls].filter((url): url is string => !!url);
}

/**
 * A proper ~150-160 char meta description, preferring the real
 * `longDescription` (Modrinth's own project body, backfilled by
 * scripts/backfill-modrinth-descriptions.ts) over the short `description`
 * tagline when it's available — the short tagline is often thin, one line,
 * or (pre-backfill) literally missing, while the source's own longer body is
 * real prose that reads better truncated to meta-description length. Falls
 * back to `description`, then to a description built entirely from other
 * real fields (name/family/source) — never fabricated copy.
 */
function metaDescriptionFor(mod: Pick<ModDetail, "name" | "gameFamilyLabel" | "source" | "description" | "longDescription">): string {
  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
  if (raw) {
    // longDescription is raw Markdown — strip the common markup so a meta
    // tag doesn't read "## Features\n- ..." verbatim, then collapse
    // whitespace/newlines into a single line before truncating.
    const plain = raw
      .replace(/```[\s\S]*?```/g, " ")
      .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/[#>*_`~-]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (plain.length <= 160) return plain;
    const cut = plain.slice(0, 157);
    const lastSpace = cut.lastIndexOf(" ");
    return `${cut.slice(0, lastSpace > 100 ? lastSpace : 157)}…`;
  }
  return `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
}

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { family, slug } = await params;
  const mod = await getCatalogMod(family, slug);
  if (!mod) return { title: "Mod not found" };
  const title = `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`;
  const description = metaDescriptionFor(mod);
  const images = realImagesFor(mod);
  const canonicalUrl = `${APP_URL}/mods/${mod.gameFamily}/${mod.slug}`;
  return {
    title,
    description,
    // The only other place this mod's detail is ever rendered is the portal
    // at /dashboard/nxlabs/[family]/[slug] — entirely disallowed in
    // app/robots.ts (`disallow: ["/dashboard", ...]`), so it's not crawlable
    // and can't compete with this page as duplicate content. This canonical
    // still costs nothing to keep as a defensive, standard tag.
    alternates: { canonical: canonicalUrl },
    openGraph: {
      title,
      description,
      type: "website",
      url: canonicalUrl,
      ...(images.length > 0 ? { images } : {}),
    },
    twitter: {
      card: images.length > 0 ? "summary_large_image" : "summary",
      title,
      description,
      ...(images.length > 0 ? { images } : {}),
    },
  };
}

export default async function ModDetailPage({ params }: Params) {
  const { family, slug } = await params;
  const mod = await getCatalogMod(family, slug);
  if (!mod) notFound();

  const user = await currentUser();
  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
    relatedCatalogMods(mod, 4),
    resolveDownloadUrl(mod),
    listModComments(mod.id, { take: 10 }),
    user ? getMyModRating(mod.id, user.id) : Promise.resolve(null),
  ]);
  const recommended = recommendedPlanFor(mod, gamePlans);
  // Real gate on "does Nxeon actually host this family" — the exact same
  // PREVIEW_GAMES lookup app/(marketing)/mods/games/[family]/page.tsx already
  // uses to decide whether its PlanConfigurator deploy section renders at
  // all. `recommended` alone already goes null for a family with zero active
  // GamePlan rows (e.g. "schedule1" — confirmed 2026-09-20, no seed data
  // exists for it), but checking PREVIEW_GAMES explicitly too means this
  // panel can never show a "Deploy" button for a family the live
  // /[game]-server-hosting pages don't actually have a page for either.
  const previewGame: PreviewGame | undefined = (PREVIEW_GAMES as Record<string, PreviewGame>)[mod.gameFamily];
  const hasHostingPlan = !!(recommended && previewGame);
  // Same deployHref() the PlanConfigurator "Deploy" button already calls
  // (components/marketing/gamelanding/PlanConfigurator.tsx) — one real path
  // onto /dashboard/deploy, never a second invented one. gamePlanId carries
  // the EXACT real plan `recommended` resolved to (order.tsx's
  // orderFromIntent resolves it straight to that tier), which is more
  // precise than reconstructing a player count the way the configurator's
  // slider has to.
  const deployUrl = hasHostingPlan
    ? deployHref({ service: "game", gameFamily: mod.gameFamily, gamePlanId: recommended!.id, region: previewGame!.deployRegion })
    : null;
  // The real /[game]-server-hosting slug for this family — NOT always the raw
  // `mod.gameFamily` key (e.g. "spaceengineers" -> "space-engineers", "gmod"
  // -> "garrys-mod"). GAME_URL_SLUG (lib/marketing/gameLocationLandings.ts)
  // is the single source of truth every other cross-link in the codebase
  // already uses; the fallback link below used to build the href from the
  // bare family key instead, which 404'd for every family whose slug isn't
  // identical to its family id (confirmed live for Space Engineers 2026-09-21).
  const hostingSlug = GAME_URL_SLUG[mod.gameFamily as GameFamily] ?? mod.gameFamily;
  const downloads = formatDownloads(mod.downloads);
  const fileSize = formatBytes(mod.fileBytes);
  // A mod's OWN screenshot/icon is the best backdrop when it has one (real
  // gallery art, blurred+dimmed so it reads as ambience, not a competing
  // image). Most catalogue entries don't carry either — confirmed live
  // 2026-09-20: every github-sourced mod (CounterStrikeSharp included) has
  // iconUrl: null and galleryUrls: [] — which is exactly why this page's
  // hero used to render nothing at all for them. Falling back to the same
  // per-game hero art the family browse page already uses
  // (GAME_ART_SLUG[family].hero) means a detail page is never blank; shown
  // less blurred/more opaque than an own-screenshot backdrop since it's
  // meant to read as "this is a real game", not just ambient texture.
  //
  // NOTE (2026-09-20 hero-visibility fix): the previous scrim
  // (`from-[var(--color-bg)] via-[var(--color-bg)]/80 to-[var(--color-bg)]/40`,
  // combined with a base image opacity of only 25–30%) was verified live to
  // render as a near-solid dark box on e.g. Valheim mod pages — the icon/
  // title row sits roughly mid-height in this section, which is exactly
  // where that gradient was ~70–80% opaque, crushing an already-faint image
  // down to ~5–9% net visibility. The gradient below keeps `from` (the very
  // bottom edge, behind the description line) fully opaque for a clean
  // blend into the Section below, but is much lighter through the middle —
  // where the hero image actually needs to read — and base opacities are
  // raised so the art itself is the dominant visual, not a fabricated
  // stand-in.
  const familyHeroSlug = GAME_ART_SLUG[mod.gameFamily as GameFamily]?.hero;
  const ownHeroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
  const heroImage = ownHeroImage ?? (familyHeroSlug ? `/games/art/${familyHeroSlug}_hero.jpg` : null);
  const heroIsGameArt = !ownHeroImage && !!heroImage;
  // Real longer body from the source's own project page (Modrinth's `body`,
  // Thunderstore's README, Steam Workshop's file_description) — null until
  // backfilled, or for sources with nothing longer to offer. Rendered
  // through lib/mod-markdown.ts, NOT lib/blog.ts's renderMarkdown — that one
  // escapes every `<` (correct for this repo's own blog prose, wrong here:
  // real Modrinth/Thunderstore bodies embed raw HTML like <center>/<details>
  // that needs to actually render). Truncated at a real paragraph/line
  // boundary, never mid-tag — see renderModBody's own doc comment.
  const longDescription = mod.longDescription
    ? renderModBody(mod.longDescription, mod.source as ModBodySource, 6000)
    : null;
  const longDescriptionHtml = longDescription?.html ?? null;

  return (
    <>
      {/* SoftwareApplication, not Product — this is a free, third-party-hosted
          download, not something Nxeon sells. price: "0" is the accurate,
          Google-documented way to mark a free application. Every field below
          is a REAL value or omitted entirely — never a guess:
            - datePublished: GameMod.createdAt, always present.
            - dateModified: GameMod.upstreamUpdatedAt (the source's own last-
              shipped date, backfilled by scripts/backfill-upstream-updated.ts)
              — omitted entirely (not "same as datePublished") when null.
            - author: GameMod.authorName, when the source published one.
            - image: the mod's real icon + gallery screenshots, in that
              order — omitted when neither exists.
            - aggregateRating: real ModRating avg/count, included ONLY when
              ratingCount > 0 — never a fabricated 0/0. */}
      <script
        type="application/ld+json"
        // eslint-disable-next-line react/no-danger
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "SoftwareApplication",
            name: mod.name,
            applicationCategory: "GameApplication",
            operatingSystem: mod.gameFamilyLabel,
            description: mod.description || `${mod.name} for ${mod.gameFamilyLabel}.`,
            datePublished: mod.createdAt,
            ...(mod.upstreamUpdatedAt ? { dateModified: mod.upstreamUpdatedAt } : {}),
            ...(mod.authorName ? { author: { "@type": "Person", name: mod.authorName } } : {}),
            ...(realImagesFor(mod).length > 0 ? { image: realImagesFor(mod) } : {}),
            ...(download ? { downloadUrl: download.url } : {}),
            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
            ...(mod.ratingCount > 0 && mod.avgRating != null
              ? {
                  aggregateRating: {
                    "@type": "AggregateRating",
                    ratingValue: mod.avgRating.toFixed(1),
                    reviewCount: mod.ratingCount,
                  },
                }
              : {}),
          }),
        }}
      />

      <section className="relative overflow-hidden">
        {heroImage && (
          <div className="absolute inset-0 -z-10">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={heroImage}
              alt=""
              className={`h-full w-full object-cover ${heroIsGameArt ? "opacity-60" : "opacity-35 blur-sm"}`}
            />
            {/* var(--color-bg), not var(--bg) — the latter is never defined in
                globals.css (only --color-bg is), so this gradient stop used to
                be silently invalid CSS. Stops are deliberately much lighter
                through `via`/`to` than the old 80%/40% — see the note above
                `familyHeroSlug` for why the previous values crushed the art
                to near-invisibility. `from` stays fully opaque so the bottom
                edge still blends cleanly into the Section below. */}
            <div className="absolute inset-0 bg-gradient-to-t from-[var(--color-bg)] via-[var(--color-bg)]/50 to-[var(--color-bg)]/10" />
          </div>
        )}
        <div className="rail-wide py-20 sm:py-28">
          <ModBackLink
            gameFamilyHref={`/mods/games/${mod.gameFamily}`}
            gameFamilyLabel={mod.gameFamilyLabel}
            fallbackHref="/mods"
            fallbackLabel="NxLabs"
          />
          <p className="mt-3 text-xs font-semibold uppercase tracking-widest text-brand-300">
            <Link href="/mods" className="hover:underline">
              NxLabs
            </Link>{" "}
            /{" "}
            <Link href={`/mods/games/${mod.gameFamily}`} className="hover:underline">
              {mod.gameFamilyLabel}
            </Link>
          </p>
          <div className="mt-3 flex flex-wrap items-center gap-4">
            {mod.iconUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
            ) : (
              <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.04] text-2xl font-bold text-[var(--fg-muted)]">
                {mod.name.slice(0, 1)}
              </div>
            )}
            <div>
              <h1 className="text-3xl font-bold text-[var(--fg)] sm:text-4xl">{mod.name}</h1>
              {mod.authorName && (
                <div className="mt-1">
                  <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />
                </div>
              )}
            </div>
          </div>
          {/* Real description, or (item 4 of the NxLabs brief) an honest
              field-derived fallback for the 0.3% of mods with no real
              description anywhere — see composedDescriptionFor's own
              comment. Never blank. */}
          <p className="mt-4 max-w-2xl text-[var(--fg-muted)]">{mod.description || composedDescriptionFor(mod)}</p>
        </div>
      </section>

      <Section wide>
        <div className="mx-auto grid max-w-5xl gap-8 lg:grid-cols-[1.4fr_1fr]">
          <div className="space-y-6">
            {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}

            {longDescriptionHtml && (
              <div className="card p-6">
                <h2 className="text-lg font-semibold text-[var(--fg)]">Description</h2>
                {/* Real body from the source's own project page (Modrinth's
                    `body`, Thunderstore's README, Steam's BBCode), rendered
                    through lib/mod-markdown.ts's escape-first/allow-list
                    renderer — a fixed set of safe tags (center, details,
                    img, a, ...) is restored from already-escaped text; see
                    that module's file header for why this is safe against
                    third-party HTML. Distinct from the short tagline already
                    shown in the header above. */}
                <div
                  className="mt-3 text-sm text-[var(--fg-muted)]"
                  // eslint-disable-next-line react/no-danger
                  dangerouslySetInnerHTML={{ __html: longDescriptionHtml }}
                />
                {longDescription?.truncated && mod.url && (
                  <a
                    href={mod.url}
                    target="_blank"
                    rel="noopener noreferrer nofollow ugc"
                    className="mt-4 inline-block text-sm font-medium text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200"
                  >
                    Read the full description on {SOURCE_LABEL[mod.source] ?? mod.source} →
                  </a>
                )}
              </div>
            )}

            <div className="card p-6">
              <h2 className="text-lg font-semibold text-[var(--fg)]">Download</h2>
              {download ? (
                <>
                  <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
                    {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
                  </a>
                </>
              ) : (
                <p className="mt-3 text-sm text-[var(--fg-muted)]">No download link is available for this entry right now.</p>
              )}

              <div className="mt-6">
                <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
              </div>

              {!mod.upstreamOk && (
                <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
                  {mod.upstreamNote || "This mod is no longer supported by its source."}
                </p>
              )}
            </div>

            <RatingsAndComments
              modId={mod.id}
              avgRating={mod.avgRating}
              ratingCount={mod.ratingCount}
              initialComments={commentsPage.comments}
              initialCursor={commentsPage.nextCursor}
              myRating={myRating}
              isLoggedIn={!!user}
              isAdmin={user?.role === "ADMIN"}
              loginHref={`/login?next=${encodeURIComponent(`/mods/${mod.gameFamily}/${mod.slug}`)}`}
            />
          </div>

          <aside className="space-y-6">
            <div className="card p-6">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Details</h2>
              <dl className="mt-4 space-y-3 text-sm">
                <Row label="Game">{mod.gameFamilyLabel}</Row>
                <Row label="Category">{mod.category}</Row>
                <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
                {mod.license && <Row label="License">{mod.license}</Row>}
                {downloads && <Row label="Downloads">{downloads}</Row>}
                {fileSize && <Row label="File size">{fileSize}</Row>}
                {mod.gameVersions.length > 0 && (
                  <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>
                )}
                {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
                {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
                {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
                <Row label="Verified">
                  {mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}
                </Row>
              </dl>
            </div>

            <div className="card p-6">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Recommended server</h2>
              {recommended ? (
                <div className="mt-4 flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
                  <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg bg-brand-500/15 text-brand-300">
                    <IconServer size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="truncate text-sm font-semibold text-[var(--fg)]">{recommended.planName}</p>
                    <p className="text-xs text-[var(--fg-muted)]">
                      {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM or higher ·{" "}
                      {formatPriceCents(recommended.priceCents)}/mo
                    </p>
                  </div>
                </div>
              ) : (
                <p className="mt-3 text-sm text-[var(--fg-muted)]">
                  {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
                </p>
              )}

              {hasHostingPlan ? (
                <Link href={deployUrl!} className="btn-primary mt-4 flex items-center justify-center gap-2">
                  Deploy {recommended!.planName}
                </Link>
              ) : (
                recommended && (
                  <Link
                    href={`/${hostingSlug}-server-hosting`}
                    className="mt-3 inline-block text-sm text-brand-300 underline underline-offset-2"
                  >
                    See {mod.gameFamilyLabel} plans
                  </Link>
                )
              )}
            </div>
          </aside>
        </div>

        {related.length > 0 && (
          <div className="mx-auto mt-16 max-w-5xl">
            <h2 className="text-lg font-semibold text-[var(--fg)]">More for {mod.gameFamilyLabel}</h2>
            <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {related.map((r) => (
                <ModCard key={r.id} mod={r} href={`/mods/${r.gameFamily}/${r.slug}`} showCategoryLabel={false} />
              ))}
            </div>
          </div>
        )}
      </Section>
    </>
  );
}

function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4">
      <dt className="text-[var(--fg-muted)]">{label}</dt>
      <dd className="text-right text-[var(--fg)]">{children}</dd>
    </div>
  );
}

