/**
 * The catalogue stores ONE category per mod, in each source's own vocabulary
 * (Modrinth-seeded "Performance", Factorio's "utilities", Vintage Story's
 * "Creatures", ...). This maps a category onto a mod_tags.py tag only where
 * the tag's own description is plainly true of it; everything else gets the
 * neutral default tile (never a guessed illustration).
 */
const TAG_OF: Record<string, string> = {
  performance: "optimization", optimization: "optimization", optimisation: "optimization",
  library: "library", "library / dependency": "library", dependency: "library", core: "library", api: "library", libraries: "library",
  utility: "utility", utilities: "utility", tools: "utility", "admin tool": "utility", "external tool": "utility",
  qol: "utility", "quality of life": "utility", "gather & qol": "utility", "user experience": "utility", hud: "utility", accessibility: "utility",
  worldgen: "worldgen", "world generation": "worldgen", world: "worldgen", structures: "worldgen",
  mobs: "mobs", creatures: "mobs", animals: "mobs", npc: "mobs", npcs: "mobs", "entity logic(ai)": "mobs", pets: "mobs", villagers: "mobs", dragons: "mobs",
  technology: "technology", automation: "technology",
  storage: "storage",
  adventure: "adventure", "travel & exploration": "adventure", loot: "adventure", "pve & events": "adventure",
  social: "social", chat: "social", "chat & discord": "social", discord: "social", "clans & social": "social", community: "social",
  minigame: "minigame", minigames: "minigame", "game mode": "minigame", "gun game & 1v1": "minigame", retakes: "minigame",
  "surf/kz/bhop": "minigame", "match & scrim": "minigame", practice: "minigame",
};
export const tagOf = (category: string): string | null => TAG_OF[category.trim().toLowerCase()] ?? null;

/** mod_tags.py ill(): kinds without their own illustration use the gear, as the design does. */
function ill(kind: string) {
  if (kind === "tick") return `<div class="ti ti-tick">${"<i></i>".repeat(16)}</div>`;
  if (kind === "nodes") return `<div class="ti ti-nodes"><i></i><i></i><i></i><i></i><b></b></div>`;
  if (kind === "terrain") return `<div class="ti ti-terrain"><i></i><i></i><i></i></div>`;
  if (kind === "path") return `<div class="ti ti-path"><i></i><i></i><i></i></div>`;
  return `<div class="ti ti-gear"><i></i><i></i></div>`;
}

/** The "What kind of mod it is" tile for a mod's real category. */
export function tagTile(category: string, source: string) {
  const t = tagOf(category);
  if (t) {
    const [label, desc, kind, c1, c2] = TAGS[t];
    return `<article class="tt" style="--c1:${c1};--c2:${c2}">${ill(kind)}<div><span class="tt-k">Catalog category: ${esc(category)}</span><h3>${esc(label)}</h3><p>${esc(desc)}</p></div></article>`;
  }
  // neutral default: the category's own name, stated as a fact, no illustration claim
  return `<article class="tt" style="--c1:#6F8DFF;--c2:#9B6BFF">${ill("nodes")}<div><span class="tt-k">Catalog category</span><h3>${esc(category)}</h3><p>Listed under ${esc(category)} on ${esc(sourceLabel(source))}.</p></div></article>`;
}

/** mods_ui.py PAL (the design's own per-category card palette) + the tag map for every other category. */
const PAL: Record<string, [string, string, string]> = {
  "cross-play": ["#6F8DFF", "#B98CFF", "core"], mods: ["#4E6BFF", "#9B6BFF", "core"], performance: ["#3FD89A", "#3EDCF2", "perf"],
  plugins: ["#FFB36B", "#FF6FA8", "gear"], gameplay: ["#3EDCF2", "#4E8DFF", "wave"], minigames: ["#E04BD6", "#7B3AF5", "target"],
};
const TAG_CARD_ILL: Record<string, string> = {
  optimization: "perf", library: "core", utility: "gear", worldgen: "wave", mobs: "wave", technology: "core",
  storage: "gear", adventure: "target", social: "wave", minigame: "target",
};
export function palette(category: string): { c1: string; c2: string; ill: string } {
  const p = PAL[category.trim().toLowerCase()];
  if (p) return { c1: p[0], c2: p[1], ill: p[2] };
  const t = tagOf(category);
  if (t) return { c1: TAGS[t][3], c2: TAGS[t][4], ill: TAG_CARD_ILL[t] };
  return { c1: "#6F8DFF", c2: "#9B6BFF", ill: "core" };
}
/** mods_ui.py ILL, verbatim. */
const CARD_ILL: Record<string, string> = {
  core: '<g stroke="rgba(255,255,255,.6)" stroke-width="2" fill="none"><path d="M10 70 H60 V40 H110 V20 H200"/><path d="M30 95 H80 V65 H170"/><circle cx="60" cy="40" r="5" fill="#fff"/><circle cx="110" cy="20" r="5" fill="#fff"/><circle cx="80" cy="65" r="5" fill="#fff"/><rect x="140" y="46" width="40" height="30" rx="7"/></g>',
  perf: '<g fill="none" stroke="rgba(255,255,255,.65)" stroke-width="2.4"><path d="M10 90 L60 70 L90 80 L130 40 L160 50 L200 14"/><path d="M185 12 L201 13 L199 29"/><path d="M10 104 H200" opacity=".4"/></g>',
  gear: '<g fill="none" stroke="rgba(255,255,255,.6)" stroke-width="2.4"><circle cx="100" cy="60" r="16"/><path d="M100 26 V38 M100 82 V94 M66 60 H78 M122 60 H134 M76 36 L84 44 M116 76 L124 84 M76 84 L84 76 M116 44 L124 36"/><circle cx="100" cy="60" r="34" opacity=".35"/></g>',
  wave: '<g fill="none" stroke="rgba(255,255,255,.65)" stroke-width="2.4"><path d="M0 70 Q50 30 100 60 T200 50"/><path d="M0 92 Q60 55 110 80 T200 72" opacity=".6"/><circle cx="100" cy="60" r="6" fill="#fff"/></g>',
  target: '<g fill="none" stroke="rgba(255,255,255,.65)" stroke-width="2.2"><circle cx="100" cy="60" r="36"/><circle cx="100" cy="60" r="20"/><circle cx="100" cy="60" r="6" fill="#fff"/><path d="M100 12 V30 M100 90 V108 M52 60 H70 M130 60 H148"/></g>',
};

/** Real icon when the source published one, else the design's monogram letter(s). */
export function iconOr(m: { name: string; iconUrl: string | null }, letters = 1) {
  const initial = esc(m.name.slice(0, letters));
  return m.iconUrl
    ? `<img src="${attr(m.iconUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" style="width:100%;height:100%;object-fit:cover;border-radius:inherit" onerror="this.replaceWith(document.createTextNode('${initial.replace(/'/g, "")}'))">`
    : initial;
}

/** mods_ui.py card(): the mod card used by the per-game rails, browse grid and related rail. */
export function xmodCard(m: ModSummary, uid: string, badge = "", opts: { showGame?: boolean } = {}) {
  const { c1, c2, ill: k } = palette(m.category);
  const d = dl(m.downloads);
  const src = sourceLabel(m.source);
  const up = ago(m.upstreamUpdatedAt);
  const kLine = opts.showGame ? `${m.gameFamilyLabel} · ${m.category}` : `${m.category} · ${src}`;
  return (
    `<a class="xmod" href="${attr(modHref(m))}" style="--c1:${c1};--c2:${c2}" data-c="${attr(m.category)}" data-n="${attr(m.name.toLowerCase())}" data-dl="${m.downloads ?? 0}" data-up="${daysSince(m.upstreamUpdatedAt)}">` +
    `<div class="mc-art"><svg viewBox="0 0 200 110" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="mg${uid}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs><rect width="200" height="110" fill="url(#mg${uid})"/><circle cx="180" cy="0" r="70" fill="rgba(255,255,255,.1)"/>${CARD_ILL[k]}</svg>${badge}<span class="mc-mono">${iconOr(m)}</span></div>` +
    `<div class="mc-b"><h3>${esc(m.name)}</h3><p class="mc-k">${esc(kLine)}</p><p class="mc-d">${esc(m.description || "")}</p>` +
    `<div class="mc-f">${d ? `<span class="mc-s">${d} downloads</span>` : `<span class="mc-s">${esc(src)} listing</span>`}${up ? `<span class="mc-u">${up}</span>` : ""}${m.verified ? '<span class="mc-v" title="Verified">✓</span>' : ""}</div></div></a>`
  );
}

/** The hub's editor's-pick card (nxlabs body .npk), from a real mod. */
export function npkCard(m: ModSummary, i: number, hero = false) {
  const { c1, c2, ill: k } = palette(m.category);
  const up = ago(m.upstreamUpdatedAt);
  const d = dl(m.downloads);
  const art = CARD_ILL[k].replace("<g ", '<g transform="translate(0 5)" ');
  const foot = up ? `<em>Updated ${up}</em>` : m.verified ? "<em>Verified</em>" : "";
  const desc = (m.description || "") + (d && hero ? ` ${d} downloads.` : "");
  return (
    `<a class="npk${hero ? " npk-hero" : ""}" href="${attr(modHref(m))}" style="--c1:${c1};--c2:${c2}"><div class="npk-art"><svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="pa${i}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient><radialGradient id="pg${i}" cx=".85" cy=".1" r=".7"><stop offset="0" stop-color="#fff" stop-opacity=".3"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><rect width="200" height="120" fill="url(#pa${i})"/><rect width="200" height="120" fill="url(#pg${i})"/>${art}</svg><span class="npk-cat">${esc(m.category)}</span></div>` +
    `<div class="npk-b"><span class="npk-mono">${iconOr(m)}</span><p class="npk-k">${esc(m.gameFamilyLabel)}</p><h3>${esc(m.name)}</h3><p class="npk-d">${esc(desc.trim())}</p><span class="npk-f"><span class="src">${esc(sourceLabel(m.source))}</span>${foot}<span class="npk-go">Open →</span></span></div></a>`
  );
}

/** Palette (typeahead) row data for the page script — real mods only. */
export const palItem = (m: ModSummary) => ({
  n: m.name, g: m.gameFamilyLabel, c: m.category, d: dl(m.downloads) ?? "", s: sourceLabel(m.source), p: modHref(m),
  i: m.iconUrl ?? "",
});

/** ItemList JSON-LD for a list of real mod pages. */
export function itemListLd(name: string, mods: ModSummary[]) {
  return {
    "@context": "https://schema.org", "@type": "ItemList", name,
    itemListElement: mods.map((m, i) => ({
      "@type": "ListItem", position: i + 1, name: m.name,
      url: `https://nxeon.cloud/mods/${seg(m.gameFamily)}/${seg(m.slug)}`,
    })),
  };
}

