import "server-only";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import {
  listFeaturedMods,
  listTopDownloadedMods,
  queryCatalogMods,
  totalDownloadsFor,
  type CatalogSort,
  type ModSummary,
} from "@/lib/mods-catalog";
import { esc, type NxmLoad } from "./lib";
import {
  TAGS, attr, at, browseHref, btnGhost, countParts, dl, families, gameArt, gameHref, hubHref, iconOr, itemListLd,
  mono2, n, npkCard, palItem, palette, sourceLabel, tagOf, type Family,
} from "./mods-lib";

/**
 * /mods — the NxLabs hub. Every game tile, count, total, featured pick,
 * ranking and search result is read from the catalogue at request time
 * (lib/mods-catalog.ts, public = active && upstreamOk).
 *
 * Search hits the real catalogue: the hero search submits here with ?q=
 * (queryCatalogMods across every game, rendered as a results section), or,
 * with a game picked, goes straight to that game's browse page with ?q=.
 */
const SORTS: Record<string, { sort: CatalogSort; label: string }> = {
  featured: { sort: "featured", label: "Featured first" },
  downloads: { sort: "downloads", label: "Most downloaded" },
  latest: { sort: "latest", label: "Newest in NxLabs" },
};
const PER = 24;

/** Au icon per mod_tags.py tag, for the "Browse by what you need" tiles. */
const TAG_ICON: Record<string, string> = {
  optimization: "bolt", library: "cpu", utility: "gear", worldgen: "globe", mobs: "spark", technology: "terminal",
  storage: "database", adventure: "rocket", social: "users", minigame: "game",
};

async function totals() {
  const fams = await families();
  const total = fams.reduce((s, f) => s + f.count, 0);
  if (!fams.length || !total) throw new Error("nxm nxlabs: the public mod catalogue is empty");
  return { fams, total };
}

export async function meta(p: Record<string, string>) {
  const { fams, total } = await totals();
  const q = (p.q ?? "").trim();
  return {
    title: q ? `“${q}” mods and plugins — NxLabs` : "NxLabs — Free Mods, Plugins & Server Add-ons",
    description: `NxLabs is Nxeon’s free, public mod and plugin catalog, verified against each mod’s own source. ${n(total)} mods across ${fams.length} games, no account required.`,
  };
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const q = (p.q ?? "").trim().slice(0, 100);
  const { fams, total } = await totals();

  // A game picked in the hero palette: search that game's full browse page.
  if (q && p.game && fams.some((f) => f.family === p.game)) redirect(browseHref(p.game, { q }));

  const [totalDl, featured, top, bySource, byFamCat, famDl, results] = await Promise.all([
    totalDownloadsFor(),
    listFeaturedMods(undefined, 9),
    listTopDownloadedMods(undefined, 10),
    db.gameMod.groupBy({ by: ["source"], where: { active: true, upstreamOk: true }, _count: true }),
    db.gameMod.groupBy({ by: ["gameFamily", "category"], where: { active: true, upstreamOk: true }, _count: true }),
    db.gameMod.groupBy({ by: ["gameFamily"], where: { active: true, upstreamOk: true }, _sum: { downloads: true } }),
    resultsSection(p, q, fams),
  ]);

  // Typeahead: each game's own leading mods (featured first, then downloads), all real rows.
  const perFamily = await Promise.all(fams.map((f) => queryCatalogMods({ family: f.family, sort: "featured", perPage: 6 })));
  const palMods = [...featured, ...top, ...perFamily.flatMap((r) => r.mods)];
  const seen = new Set<string>();
  const mods = palMods.filter((m) => (seen.has(m.id) ? false : (seen.add(m.id), true))).map(palItem);

  // Game chips: the five games whose mods are downloaded most (real sums).
  const dlOf = new Map(famDl.map((r) => [r.gameFamily, r._sum.downloads ?? 0]));
  const popular = [...fams].sort((a, b) => (dlOf.get(b.family) ?? 0) - (dlOf.get(a.family) ?? 0)).slice(0, 5);
  const chips = popular.map((f) => `<button type="button" class="hq" data-g="${attr(f.label)}" data-f="${attr(f.family)}" aria-pressed="false">${esc(f.label)}</button>`).join("");

  const sources = [...bySource].sort((a, b) => b._count - a._count).map((s) => `<span>${esc(sourceLabel(s.source))}</span>`).join("");

  const cp = countParts(totalDl);
  const [big, rest] = [fams.slice(0, 3), fams.slice(3)];
  const bigHtml = big.map((f, i) => {
    const art = gameArt(f.family).hero;
    return `<a class="gbig" href="${attr(gameHref(f.family))}" data-n="${attr(f.label.toLowerCase())}">${art ? `<img src="${art}" alt="" width="640" height="360">` : ""}<span class="gbig-b"><small>#${i + 1} by catalog size</small><b>${esc(f.label)}</b><em>${n(f.count)} mods</em><span class="gbig-go">Browse mods →</span></span></a>`;
  }).join("");
  const gridHtml = rest.map((f) => {
    const art = gameArt(f.family).poster;
    return `<a class="gp" href="${attr(gameHref(f.family))}" data-n="${attr(f.label.toLowerCase())}">${art ? `<img src="${art}" alt="" loading="lazy" width="360" height="520">` : `<span class="gp-mono">${esc(mono2(f.label))}</span>`}<span class="gp-b"><b>${esc(f.label)}</b><em>${n(f.count)} mods</em></span></a>`;
  }).join("");

  const cats = await catsSection(byFamCat);
  const demo = await installDemo(top);

  return {
    slots: {
      "games.n": String(fams.length),
      "mods.total": n(total),
      "mods.totalRaw": String(total),
      "dl.v": cp.value, "dl.dec": String(cp.dec), "dl.suf": cp.suf,
      "pal.chips:html": chips,
      "why.sources:html": sources,
      "games.big:html": bigHtml,
      "games.grid:html": gridHtml,
      "results:html": results.html,
      "picks:html": picksSection(featured),
      "cats:html": cats,
      "top10:html": top10Section(top),
      "install.demo:html": demo.html,
      "q": q,
    },
    data: { mods, totalLabel: n(total), demoServer: demo.server },
    jsonLd: [
      ...(top.length ? [itemListLd("Most downloaded mods on NxLabs", top)] : []),
      ...(results.mods.length ? [itemListLd(`NxLabs results for “${q}”`, results.mods)] : []),
    ],
  };
}

// ── search / full-catalogue results (?q= / ?sort= / ?page=) ────────────────
async function resultsSection(p: Record<string, string>, q: string, fams: Family[]): Promise<{ html: string; mods: ModSummary[] }> {
  const sortKey = SORTS[p.sort ?? ""] ? p.sort : q ? "downloads" : undefined;
  if (!q && !sortKey && !p.page) return { html: "", mods: [] };
  const s = SORTS[sortKey ?? "downloads"];
  const page = Math.max(1, Math.floor(Number(p.page) || 1));
  const res = await queryCatalogMods({ q: q || undefined, sort: s.sort, page, perPage: PER });

  // Where the matches are, per game — real counts from the same query.
  const perGame = q
    ? (await Promise.all(fams.map(async (f) => ({ f, total: (await queryCatalogMods({ family: f.family, q, perPage: 1 })).total }))))
        .filter((x) => x.total > 0).sort((a, b) => b.total - a.total)
    : [];

  const title = q ? `Results for “${esc(q)}”` : `All mods · ${esc(s.label)}`;
  const lede = q
    ? res.total ? `${n(res.total)} ${res.total === 1 ? "mod" : "mods"} across ${perGame.length} ${perGame.length === 1 ? "game" : "games"}, searched across the whole catalog.` : "No mods match that search. Try a shorter word, or browse a game below."
    : `${n(res.total)} verified mods and plugins across every game.`;
  const sortBtns = Object.entries(SORTS).map(([k, v]) =>
    `<a class="hq" style="text-decoration:none" href="${attr(hubHref({ q: q || undefined, sort: k }))}#results" aria-pressed="${k === sortKey}">${esc(v.label)}</a>`).join("");
  const gameChips = perGame.map((x) =>
    `<a class="hq" style="text-decoration:none" href="${attr(browseHref(x.f.family, { q }))}" aria-pressed="false">${esc(x.f.label)} · ${n(x.total)}</a>`).join("");
  const cards = res.mods.map((m, i) => npkCard(m, 100 + i)).join("");
  const pager = res.totalPages > 1
    ? `<nav aria-label="Pagination" style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:26px;flex-wrap:wrap">${
        res.page > 1 ? btnGhost(hubHref({ q: q || undefined, sort: sortKey, page: res.page - 1 }) + "#results", "← Previous") : "<span></span>"
      }<span style="color:var(--muted);font-size:.86rem">Page ${n(res.page)} of ${n(res.totalPages)}</span>${
        res.page < res.totalPages ? btnGhost(hubHref({ q: q || undefined, sort: sortKey, page: res.page + 1 }) + "#results", "Next →") : "<span></span>"
      }</nav>`
    : "";
  const html = `<section class="section" id="results" aria-labelledby="rs-title"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="rs-title">${title}</h2><p class="lede">${lede}</p></div>${btnGhost(hubHref(), "Clear")}</div>
  <div class="pal-chips" role="group" aria-label="Sort" style="justify-content:flex-start;margin:0 0 12px"><span>Sort:</span>${sortBtns}</div>
  ${gameChips ? `<div class="pal-chips" role="group" aria-label="Narrow to a game" style="justify-content:flex-start;margin:0 0 22px"><span>In a game:</span>${gameChips}</div>` : ""}
  ${cards ? `<div class="pks">${cards}</div>` : ""}
  ${pager}
</div></section>`;
  return { html, mods: res.mods };
}

// ── editor's picks: real GameMod.featured rows ─────────────────────────────
function picksSection(featured: ModSummary[]) {
  if (!featured.length) return "";
  const cards = featured.map((m, i) => npkCard(m, i, i === 0)).join("");
  return `<section class="section" id="picks" aria-labelledby="pk-title" style="padding-top:0"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="pk-title">Editor’s picks</h2><p class="lede">Mods the NxLabs catalog marks as featured, across every game.</p></div>${btnGhost(hubHref({ sort: "featured" }) + "#results", "View more")}</div>
  <div class="pks">${cards}</div>
</div></section>`;
}

// ── browse by what you need: mod_tags.py tags over the real categories ─────
async function catsSection(rows: { gameFamily: string; category: string; _count: number }[]) {
  const byTag = new Map<string, { total: number; cats: Map<string, number> }>();
  for (const r of rows) {
    const t = tagOf(r.category);
    if (!t) continue;
    const e = byTag.get(t) ?? { total: 0, cats: new Map() };
    e.total += r._count;
    e.cats.set(r.category, (e.cats.get(r.category) ?? 0) + r._count);
    byTag.set(t, e);
  }
  const tags = [...byTag.entries()].sort((a, b) => b[1].total - a[1].total).slice(0, 8);
  if (tags.length < 2) return "";
  const tiles = await Promise.all(tags.map(async ([t, e]) => {
    const topCat = [...e.cats.entries()].sort((a, b) => b[1] - a[1])[0][0];
    const ex = (await queryCatalogMods({ category: topCat, sort: "downloads", perPage: 3 })).mods;
    const [label, desc, , c1, c2] = TAGS[t];
    return `<a class="ct" href="${attr(hubHref({ q: topCat }))}#results" style="--c1:${c1};--c2:${c2}"><span class="ct-ill"><span data-au-icon="${TAG_ICON[t]}"></span><i></i><i></i></span><h3>${esc(label)}</h3><p>${esc(desc)}</p><small>${esc(ex.map((m) => m.name).join(", ") || `${n(e.total)} mods`)}</small></a>`;
  }));
  return `<section class="section" id="cats" aria-labelledby="ct-title" style="padding-top:0"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="ct-title">Browse by what you need</h2><p class="lede">Start from the problem, not the file name.</p></div></div>
  <div class="cts">${tiles.join("")}</div>
</div></section>`;
}

// ── most downloaded: real downloads from each source ───────────────────────
function top10Section(top: ModSummary[]) {
  if (top.length < 3) return "";
  const mx = top[0].downloads || 1;
  const pd = (m: ModSummary, k: number) =>
    `<div class="pd p${k}">${k === 1 ? '<div class="pd-crown" aria-hidden="true">★</div>' : ""}<div class="pd-m">${iconOr(m)}</div><b><a href="${attr(at(`/mods/${encodeURIComponent(m.gameFamily)}/${encodeURIComponent(m.slug)}`))}" style="color:inherit;text-decoration:none">${esc(m.name)}</a></b><em>${dl(m.downloads) ?? ""}</em><div class="pd-b"><span>${k}</span></div></div>`;
  const podium = pd(top[1], 2) + pd(top[0], 1) + pd(top[2], 3);
  const rows = top.slice(3).map((m, i) => {
    const { c1, c2 } = palette(m.category);
    return `<li><span class="rk-n">${String(i + 4).padStart(2, "0")}</span><span class="rk-l" style="background:linear-gradient(135deg,${c1},${c2})">${iconOr(m)}</span><span class="rk-t"><b><a href="${attr(at(`/mods/${encodeURIComponent(m.gameFamily)}/${encodeURIComponent(m.slug)}`))}" style="color:inherit;text-decoration:none">${esc(m.name)}</a></b><small>${esc(m.gameFamilyLabel)} · ${esc(m.category)}</small></span><span class="rk-bar"><i style="--v:${((m.downloads ?? 0) / mx).toFixed(3)}"></i></span><span class="rk-d">${dl(m.downloads) ?? ""}</span></li>`;
  }).join("");
  return `<section class="section" id="top10" aria-labelledby="tp-title" style="padding-top:0"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="tp-title">Most downloaded</h2><p class="lede">Ranked by real download counts from each mod’s own source.</p></div>${btnGhost(hubHref({ sort: "downloads" }) + "#results", "Full ranking")}</div>
  <div class="tp2">
    <div class="podium" aria-label="Top three">${podium}</div>
    <ol class="rk" id="rk">${rows}</ol>
  </div>
</div></section>`;
}

// ── the drag-to-install illustration, stocked with real mods ───────────────
async function installDemo(top: ModSummary[]) {
  // The shelf is the most-downloaded game's own top mods, so the demo shows
  // real names and real counts; the server itself is an illustration.
  const fam = top[0]?.gameFamily;
  const mods = fam ? await listTopDownloadedMods(fam, 4) : [];
  if (mods.length < 2) throw new Error("nxm nxlabs: not enough real mods for the install illustration");
  const [pre, ...shelf] = mods;
  const server = "my-server";
  const dm = (m: ModSummary) => {
    const { c1, c2 } = palette(m.category);
    return `<div class="dm" data-k="${attr(m.slug)}" style="--c1:${c1};--c2:${c2}"><span class="dm-grip" aria-hidden="true"></span><span class="dm-l">${esc(m.name[0])}</span><span class="dm-t"><b>${esc(m.name)}</b><small>${esc(m.category)}${dl(m.downloads) ? ` · ${dl(m.downloads)}` : ""}</small></span><button type="button">Add</button></div>`;
  };
  const pc = palette(pre.category);
  const html = `<div class="dd-shelf" id="shelf"><p class="dd-k">${esc(pre.gameFamilyLabel)} · example</p>
      ${shelf.map(dm).join("\n      ")}</div>
