import "server-only";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import {
  listCategoryCounts,
  listFeaturedMods,
  listRecentlyUpdatedMods,
  listTopDownloadedMods,
  queryCatalogMods,
  type ModSummary,
} from "@/lib/mods-catalog";
import { esc, introSpan, productLd, usd, type NxmLoad } from "./lib";
import {
  TAGS, ago, attr, browseHref, btnDeploy, btnGhost, dl, familyInstallable, familyOr404, familyPlans, gameArt,
  itemListLd, loaderLabel, n, palItem, palette, tagOf, tierPrice, tierRam, xmodCard, type Family, type FamilyPlans,
} from "./mods-lib";

/**
 * /mods/games/[family] — the Minecraft mods design as the per-game template
 * for every family listCatalogFamilies() returns (unknown family -> 404).
 * Counts, picks, rails, categories and loaders come from the catalogue; the
 * game-server upsell from that family's real db.gamePlan tiers (hidden when
 * the family has none); deploy links via deployHref().
 */
const ICON: Record<string, string> = {
  optimization: "bolt", library: "cpu", utility: "gear", worldgen: "globe", mobs: "spark", technology: "terminal",
  storage: "database", adventure: "rocket", social: "users", minigame: "game",
};

export async function meta(p: Record<string, string>) {
  const f = await familyOr404(p.family);
  const art = gameArt(f.family).hero;
  return {
    title: `${f.label} Mods & Plugins — NxLabs`,
    description: `Browse ${n(f.count)} verified ${f.label} mods and plugins with real download counts, licenses and version support — download free${familyInstallable(f.family) ? ", or add straight to your Nxeon server" : " from each mod’s own source"}.`,
    crumb: `${f.label} mods`,
    ...(art ? { image: art } : {}),
  };
}

/** Real loaders/platforms across a family's public mods (GameMod.loaders), most used first. */
async function familyLoaders(family: string): Promise<string[]> {
  const rows = await db.$queryRaw<{ l: string; c: bigint }[]>(Prisma.sql`
    SELECT l, COUNT(*) AS c FROM "GameMod", unnest("loaders") AS l
    WHERE "gameFamily" = ${family} AND "active" = true AND "upstreamOk" = true
    GROUP BY l ORDER BY c DESC LIMIT 6`);
  return rows.map((r) => loaderLabel(r.l));
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const f = await familyOr404(p.family);
  const [featured, top, fresh, cats, loaders, plans, palette6] = await Promise.all([
    listFeaturedMods(f.family, 5),
    listTopDownloadedMods(f.family, 12),
    listRecentlyUpdatedMods(f.family, 12),
    listCategoryCounts(f.family),
    familyLoaders(f.family),
    familyPlans(f.family),
    queryCatalogMods({ family: f.family, sort: "featured", perPage: 60 }),
  ]);
  const inst = familyInstallable(f.family);
  const art = gameArt(f.family).hero;
  const browse = browseHref(f.family);
  const seen = new Set<string>();
  const mods = [...featured, ...top, ...palette6.mods].filter((m) => (seen.has(m.id) ? false : (seen.add(m.id), true))).map(palItem);

  return {
    slots: {
      "game.name": f.label,
      "game.count": n(f.count),
      "game.countRaw": String(f.count),
      "game.href": `/nxm/mods/games/${encodeURIComponent(f.family)}`,
      "game.heroStyle": art ? `background-image:url(${art})` : "background-image:none",
      "game.subTail": inst
        ? "Free to download, one click to add to an Nxeon server."
        : "Free to download from each mod’s own source.",
      "browse.href": browse,
      "loaders:html": loaders.length
        ? `<div class="mgh-loaders"><small>Loaders and platforms</small>${loaders.map((l) => `<span>${esc(l)}</span>`).join("")}</div>`
        : "",
      "aside:html": asideHtml(f, plans, inst),
      "start:html": startHtml(f, featured, inst),
      "popular:html": railHtml("popular", "po-title", "Most downloaded", "Ranked by real download counts from each mod’s own source.",
        browseHref(f.family, { sort: "downloads" }), `Most downloaded ${f.label} mods`, top,
        (m, i) => xmodCard(m, `p${i}`, `<span class="mc-rank${i < 3 ? " g" : ""}">#${i + 1}</span>`), ""),
      "fresh:html": railHtml("fresh", "fr-title", "Recently updated", "Real last-shipped times from each source.",
        browseHref(f.family, { sort: "latest" }), `Recently updated ${f.label} mods`, fresh,
        (m, i) => xmodCard(m, `n${i}`, `<span class="mc-new">Updated ${ago(m.upstreamUpdatedAt)}</span>`), ' style="padding-top:0"'),
      "cats:html": await catsHtml(f, cats),
      "plans:html": plansHtml(f, plans, inst),
      "faq.install": inst
        ? `Yes. If you run an Nxeon ${f.label} server, log in and use “Add to my server.” The mod is installed and your server restarts with it enabled.`
        : `Not automatically yet: NxLabs can’t place ${f.label} mods for you. Download a mod from its source and upload it to your Nxeon ${f.label} server in Files.`,
      "final:html": finalHtml(f, plans, inst),
    },
    data: { mods, totalLabel: n(f.count) },
    crumb: `${f.label} mods`,
    jsonLd: [
      ...(top.length ? [itemListLd(`Most downloaded ${f.label} mods`, top)] : []),
      ...(plans.tiers.length
        ? [productLd(`${f.label} server hosting`, `Nxeon ${f.label} game servers for running ${f.label} mods.`, `/mods/games/${f.family}`,
            plans.tiers.map((t) => ({ name: t.name, price: t.i ?? t.p })))]
        : []),
    ],
  };
}

function deployGame(f: Family, plans: FamilyPlans) {
  return deployHref({ service: "game", gameFamily: f.family, gamePlanId: plans.featuredId ?? plans.cheapest?.id });
}

function asideHtml(f: Family, plans: FamilyPlans, inst: boolean) {
  if (!plans.cheapest) return "";
  return `<aside class="mgs" aria-label="Deploy a ${attr(f.label)} server"><div class="mgs-top"><span class="srv-dot"></span><b>${esc(f.label)} server</b><em>Ready in about a minute</em></div><p class="mgs-p">From <b>${tierPrice(plans.cheapest)}</b>/month</p><ul><li><span data-au-icon="rocket" data-grad></span>${inst ? "One-click mods from NxLabs" : "Full file access for your mods"}</li><li><span data-au-icon="shield" data-grad></span>DDoS protection included</li><li><span data-au-icon="backup" data-grad></span>Daily restore points</li></ul>${btnDeploy(deployGame(f, plans), `Deploy a ${f.label} server`)}</aside>`;
}

/** "Start here": the family's real featured mods (GameMod.featured), hidden when none are marked. */
function startHtml(f: Family, featured: ModSummary[], inst: boolean) {
  if (!featured.length) return "";
  const items = featured.map((m, i) => {
    const { c1, c2 } = palette(m.category);
    return `<label class="es" style="--c1:${c1};--c2:${c2}"><input type="checkbox" data-n="${attr(m.name)}" ${i < 3 ? "checked" : ""}><span class="es-l">${esc(m.name[0])}</span><span class="es-t"><b>${esc(m.name)}</b><small>${esc(m.description || m.category)}</small></span><span class="es-m"><em>${esc(m.category)}</em><i>${dl(m.downloads) ?? ""}</i></span><span class="es-c" aria-hidden="true"></span></label>`;
  }).join("");
  const go = inst
    ? `<a class="nxm-btn" id="es-go" href="/dashboard/nxlabs/games/${attr(encodeURIComponent(f.family))}"><span class="nxm-bt">Add them in my dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
    : `<a class="nxm-btn" id="es-go" href="${attr(browseHref(f.family))}"><span class="nxm-bt">Browse all ${esc(f.label)} mods</span><span class="nxm-arw" aria-hidden="true">→</span></a>`;
  return `<section class="section" id="start" aria-labelledby="st-title"><div class="container ess">
  <div><span class="au-chip"><i class="d"></i>Start here</span><h2 class="h2" id="st-title">The essentials for a modded ${esc(f.label)} server</h2><p class="lede">The ${esc(f.label)} mods the NxLabs catalog marks as featured. Pick what you want${inst ? ", then add them to your server from your dashboard" : ", then grab each one from its source"}.</p>
    <div class="ess-sum au-glass"><div><b id="es-n">${Math.min(3, featured.length)}</b> mods selected</div><div class="ess-bar"><i id="es-bar"></i></div>${go}</div></div>
  <div class="ess-list" id="ess">${items}</div>
</div></section>`;
}

function railHtml(id: string, hid: string, title: string, lede: string, viewAll: string, aria: string, mods: ModSummary[],
  card: (m: ModSummary, i: number) => string, style: string) {
  if (!mods.length) return "";
  return `<section class="section mrow-s" id="${id}" aria-labelledby="${hid}"${style}><div class="container">
  <div class="mrow-h"><div><h2 class="h2" id="${hid}">${esc(title)}</h2><p class="lede">${esc(lede)}</p></div><div class="mrow-c"><a class="va" href="${attr(viewAll)}">View all<span aria-hidden="true">→</span></a><button type="button" class="cb prev" aria-label="Previous">‹</button><button type="button" class="cb next" aria-label="Next">›</button></div></div>
  <div class="mrow" tabindex="0" aria-label="${attr(aria)}">${mods.map(card).join("")}</div>
</div></section>`;
}

/** The family's real categories (DB-wide counts), each tile with its own top mods. */
async function catsHtml(f: Family, cats: { category: string; count: number }[]) {
  const top = cats.slice(0, 6);
  if (top.length < 2) return "";
  const tiles = await Promise.all(top.map(async (c) => {
    const ex = (await queryCatalogMods({ family: f.family, category: c.category, sort: "downloads", perPage: 3 })).mods;
    const t = tagOf(c.category);
    const { c1, c2 } = palette(c.category);
    const desc = t ? TAGS[t][1] : `${n(c.count)} ${f.label} ${c.count === 1 ? "mod" : "mods"} listed under ${c.category}.`;
    return `<a class="ct" href="${attr(browseHref(f.family, { category: c.category }))}" style="--c1:${c1};--c2:${c2}"><span class="ct-ill"><span data-au-icon="${t ? ICON[t] : "spark"}"></span><i></i><i></i></span><h3>${esc(c.category)}</h3><p>${esc(desc)}</p><small>${esc(ex.map((m) => m.name).join(", "))}</small></a>`;
  }));
  return `<section class="section" id="cats" aria-labelledby="ct-title" style="padding-top:0"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="ct-title">Browse ${esc(f.label)} by what you need</h2></div></div>
  <div class="cts cts6">${tiles.join("")}</div>
</div></section>`;
}

function plansHtml(f: Family, plans: FamilyPlans, inst: boolean) {
  if (!plans.tiers.length) return "";
  const cards = plans.tiers.map((t) => {
    const pop = t.id === plans.featuredId;
    const spec = [t.slots ? `${t.slots} players` : null, `${t.cpu} vCPU`, `${t.disk} GB NVMe`].filter(Boolean).join(" · ");
    const intro = t.i != null ? `<p>Then ${usd(Math.round(t.p * 100))}/month after the ${introSpan(t.it)}</p>` : "";
    const btn = pop ? btnDeploy(t.href, `Deploy ${tierRam(t)}`).replace("<span class=\"ar\">→</span>", "") : btnGhost(t.href, `Deploy ${tierRam(t)}`);
    return `<article class="mp${pop ? " pop" : ""}">${pop ? "<span class=tag>Most popular</span>" : ""}<b>${tierRam(t)}</b><p class="mp-p"><em>${tierPrice(t)}</em>/month</p><p>${esc(spec)}</p>${intro}${btn}</article>`;
  }).join("");
  return `<section class="section" id="plans" aria-labelledby="pl-title" style="padding-top:0"><div class="container mpl">
  <div><h2 class="h2" id="pl-title">Run them on a ${esc(f.label)} server</h2><p class="lede">${inst
    ? `Every Nxeon ${esc(f.label)} server can add NxLabs mods in one click, with DDoS protection and daily restore points included.`
    : `Every Nxeon ${esc(f.label)} server gives you full file access for mods, with DDoS protection and daily restore points included.`}</p>${btnGhost("/nxm/game-servers", "All sizes and games")}</div>
  <div class="mps">${cards}</div>
</div></section>`;
}

function finalHtml(f: Family, plans: FamilyPlans, inst: boolean) {
  const more = `<a class="nxm-glassbtn" href="/nxm/mods"><span class="nxm-bt">All games on NxLabs</span></a>`;
  if (!plans.cheapest) return `<p>Every mod links to its real source, free to download.</p><div class="final-ctas">${btnDeploy(browseHref(f.family), `Browse all ${f.label} mods`)}${more}</div>`;
  return `<p>Deploy in about a minute from ${tierPrice(plans.cheapest)} a month${inst ? " and add mods in one click" : ", then upload your mods in Files"}.</p><div class="final-ctas">${btnDeploy(deployGame(f, plans), `Deploy a ${f.label} server`)}${more}</div>`;
}

