  const tiles = await Promise.all(top.map(async (c) => {
    const ex = (await queryCatalogMods({ family: f.family, category: c.category, sort: "downloads", perPage: 3 })).mods;
    const t = tagOf(c.category);
    const { c1, c2 } = palette(c.category);
    const desc = t ? TAGS[t][1] : `${n(c.count)} ${f.label} ${c.count === 1 ? "mod" : "mods"} listed under ${c.category}.`;
    return `<a class="ct" href="${attr(browseHref(f.family, { category: c.category }))}" style="--c1:${c1};--c2:${c2}"><span class="ct-ill"><span data-au-icon="${t ? ICON[t] : "spark"}"></span><i></i><i></i></span><h3>${esc(c.category)}</h3><p>${esc(desc)}</p><small>${esc(ex.map((m) => m.name).join(", "))}</small></a>`;
  }));
  return `<section class="section" id="cats" aria-labelledby="ct-title" style="padding-top:0"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="ct-title">Browse ${esc(f.label)} by what you need</h2></div></div>
  <div class="cts cts6">${tiles.join("")}</div>
</div></section>`;
}

function plansHtml(f: Family, plans: FamilyPlans, inst: boolean) {
  if (!plans.tiers.length) return "";
  const cards = plans.tiers.map((t) => {
    const pop = t.id === plans.featuredId;
    const spec = [t.slots ? `${t.slots} players` : null, `${t.cpu} vCPU`, `${t.disk} GB NVMe`].filter(Boolean).join(" · ");
    const intro = t.i != null ? `<p>Then ${usd(Math.round(t.p * 100))}/month after the ${introSpan(t.it)}</p>` : "";
    const btn = pop ? btnDeploy(t.href, `Deploy ${tierRam(t)}`).replace("<span class=\"ar\">→</span>", "") : btnGhost(t.href, `Deploy ${tierRam(t)}`);
    return `<article class="mp${pop ? " pop" : ""}">${pop ? "<span class=tag>Most popular</span>" : ""}<b>${tierRam(t)}</b><p class="mp-p"><em>${tierPrice(t)}</em>/month</p><p>${esc(spec)}</p>${intro}${btn}</article>`;
  }).join("");
  return `<section class="section" id="plans" aria-labelledby="pl-title" style="padding-top:0"><div class="container mpl">
  <div><h2 class="h2" id="pl-title">Run them on a ${esc(f.label)} server</h2><p class="lede">${inst
    ? `Every Nxeon ${esc(f.label)} server can add NxLabs mods in one click, with DDoS protection and daily restore points included.`
    : `Every Nxeon ${esc(f.label)} server gives you full file access for mods, with DDoS protection and daily restore points included.`}</p>${btnGhost("/nxm/game-servers", "All sizes and games")}</div>
  <div class="mps">${cards}</div>
</div></section>`;
}

function finalHtml(f: Family, plans: FamilyPlans, inst: boolean) {
  const more = `<a class="nxm-glassbtn" href="/nxm/mods"><span class="nxm-bt">All games on NxLabs</span></a>`;
  if (!plans.cheapest) return `<p>Every mod links to its real source, free to download.</p><div class="final-ctas">${btnDeploy(browseHref(f.family), `Browse all ${f.label} mods`)}${more}</div>`;
  return `<p>Deploy in about a minute from ${tierPrice(plans.cheapest)} a month${inst ? " and add mods in one click" : ", then upload your mods in Files"}.</p><div class="final-ctas">${btnDeploy(deployGame(f, plans), `Deploy a ${f.label} server`)}${more}</div>`;
}

