import "server-only";
import { notFound } from "next/navigation";
import { listCategoryCounts, queryCatalogMods, type CatalogSort } from "@/lib/mods-catalog";
import { esc, type NxmLoad } from "./lib";
import { attr, browseHref, familyOr404, gameHref, itemListLd, n, xmodCard, type Family } from "./mods-lib";

/**
 * /mods/games/[family]/all — the "All Minecraft mods" design as the paginated,
 * filterable, searchable browse page for every family. One real
 * queryCatalogMods() call per request: ?q (name/category/description search),
 * ?category (the family's real categories), ?sort, ?page. Totals are real
 * counts, never the design's snapshot.
 */
const PER = 12;
const SORTS: { key: string; sort: CatalogSort; label: string }[] = [
  { key: "downloads", sort: "downloads", label: "Most downloaded" },
  { key: "latest", sort: "latest", label: "Newest in NxLabs" },
  { key: "featured", sort: "featured", label: "Featured first" },
];
const DEFAULT_SORT = "downloads";

type Q = { q: string; category: string; sort: string; page: number };
function parse(p: Record<string, string>): Q {
  return {
    q: (p.q ?? "").trim().slice(0, 100),
    category: (p.category ?? "").trim(),
    sort: SORTS.some((s) => s.key === p.sort) ? p.sort : DEFAULT_SORT,
    page: Math.max(1, Math.floor(Number(p.page) || 1)),
  };
}
const link = (f: Family, q: Q, over: Partial<Q>) => {
  const v = { ...q, ...over };
  return browseHref(f.family, {
    q: v.q || undefined, category: v.category || undefined,
    sort: v.sort !== DEFAULT_SORT ? v.sort : undefined, page: v.page > 1 ? v.page : undefined,
  });
};

async function categories(f: Family, q: Q) {
  const cats = await listCategoryCounts(f.family);
  // fail closed: a category this game doesn't have is not a page
  if (q.category && !cats.some((c) => c.category === q.category)) notFound();
  return cats;
}

export async function meta(p: Record<string, string>) {
  const f = await familyOr404(p.family);
  const q = parse(p);
  await categories(f, q);
  const bits = [q.category, q.q && `“${q.q}”`, q.page > 1 && `page ${q.page}`].filter(Boolean).join(", ");
  return {
    title: `All ${f.label} mods${bits ? ` (${bits})` : ""} | NxLabs by Nxeon`,
    description: `Browse all ${n(f.count)} verified ${f.label} mods and plugins, each linked to its real source, with real download counts.`,
    crumb: `All ${f.label} mods`,
  };
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const f = await familyOr404(p.family);
  const q = parse(p);
  const [cats, res] = await Promise.all([
    categories(f, q),
    queryCatalogMods({
      family: f.family, q: q.q || undefined, category: q.category || undefined,
      sort: SORTS.find((s) => s.key === q.sort)!.sort, page: q.page, perPage: PER,
    }),
  ]);
  const cur = { ...q, page: res.page };

  const sortHtml = SORTS.map((s) =>
    `<button type="button" data-s="${s.key}" data-href="${attr(link(f, cur, { sort: s.key, page: 1 }))}" aria-pressed="${s.key === q.sort}">${esc(s.label)}</button>`).join("");

  // chips: the game's real categories by size; the active one always shown
  let shown = cats.slice(0, 8);
  if (q.category && !shown.some((c) => c.category === q.category)) shown = [...shown, cats.find((c) => c.category === q.category)!];
  const chip = (label: string, cat: string, count: number | null) =>
    `<button type="button" class="fc" data-c="${attr(cat)}" data-href="${attr(link(f, cur, { category: cat, page: 1 }))}" aria-pressed="${cat === q.category}">${esc(label)}${count != null ? ` <small style="opacity:.6">${n(count)}</small>` : ""}</button>`;
  const chipsHtml = cats.length > 1 ? chip("All", "", null) + shown.map((c) => chip(c.category, c.category, c.count)).join("") : "";

  const from = res.total ? (res.page - 1) * res.perPage + 1 : 0;
  const to = Math.min(res.total, res.page * res.perPage);
  const scope = [q.category && `in ${q.category}`, q.q && `for “${q.q}”`].filter(Boolean).join(" ");
  const countText = res.total ? `Showing ${n(from)}–${n(to)} of ${n(res.total)}${scope ? ` ${scope}` : ""}` : `No ${f.label} mods ${scope || "yet"}`;

  const grid = res.mods.map((m, i) => xmodCard(m, `b${i}`)).join("");
  const empty = res.total
    ? ""
    : `<p class="mb-empty" id="mb-empty">No ${esc(f.label)} mods match. Try another category, or <a href="${attr(browseHref(f.family))}">clear the search</a>.</p>`;

  return {
    slots: {
      "game.name": f.label,
      "game.href": gameHref(f.family),
      "browse.href": browseHref(f.family),
      "game.count": n(f.count),
      "q": q.q,
      "hidden:html": [q.category && `<input type="hidden" name="category" value="${attr(q.category)}">`,
        q.sort !== DEFAULT_SORT && `<input type="hidden" name="sort" value="${attr(q.sort)}">`].filter(Boolean).join(""),
      "sort:html": sortHtml,
      "chips:html": chipsHtml,
      "count": countText,
      "grid:html": grid,
      "empty:html": empty,
      "pager:html": pager(f, cur, res.totalPages),
    },
    data: {},
    crumb: `All ${f.label} mods`,
    jsonLd: res.mods.length ? [itemListLd(`All ${f.label} mods, page ${res.page}`, res.mods)] : [],
  };
}

function pager(f: Family, q: Q, pages: number) {
  if (pages <= 1) return "";
  const p = q.page;
  const want = [...new Set([1, p - 2, p - 1, p, p + 1, p + 2, pages])].filter((x) => x >= 1 && x <= pages).sort((a, b) => a - b);
  let nums = "", last = 0;
  for (const x of want) {
    if (last && x - last > 1) nums += '<span class="pg-gap">…</span>';
    nums += `<a class="pg-n${x === p ? " on" : ""}" href="${attr(link(f, q, { page: x }))}"${x === p ? ' aria-current="page"' : ""}>${n(x)}</a>`;
    last = x;
  }
  const prev = p > 1 ? `<a class="pg-prev" href="${attr(link(f, q, { page: p - 1 }))}" rel="prev">← Previous</a>` : '<span class="pg-prev is-off" aria-disabled="true">← Previous</span>';
  const next = p < pages ? `<a class="pg-next" href="${attr(link(f, q, { page: p + 1 }))}" rel="next">Next →</a>` : '<span class="pg-next is-off" aria-disabled="true">Next →</span>';
  return `<nav class="pgn" aria-label="Pagination">${prev}<div class="pg-nums">${nums}</div>${next}</nav>
  <p class="pg-note">Page ${n(p)} of ${n(pages)} · ${PER} per page</p>`;
}

