import "server-only";
import { notFound } from "next/navigation";
import { currentUser } from "@/lib/auth";
import { deployHref } from "@/lib/deploy-intent";
import { getEligibleServersForMod } from "@/lib/actions-mods";
import { renderModBody, type ModBodySource } from "@/lib/mod-markdown";
import {
  composedDescriptionFor,
  formatBytes,
  getCatalogMod,
  recommendedPlanFor,
  relatedCatalogMods,
  resolveDownloadUrl,
  type ModDetail,
} from "@/lib/mods-catalog";
import { esc, introSpan, usd, type NxmLoad } from "./lib";
import {
  ago, at, attr, browseHref, btnDeploy, btnGlass, dl, familyOr404, familyPlans, gameHref, iconOr, installable, loaderLabel,
  modHref, n, palette, portalModHref, regionsWithFlags, sourceLabel, tagTile, tierPrice, tierRam, xmodCard, type Family, type FamilyPlans,
} from "./mods-lib";

/**
 * /mods/[family]/[slug] — the Lithium design as the template for every mod.
 * Three layers (docs/HANDOFF.md):
 *   1. automatic, from the mod's real GameMod row (name, author, stats,
 *      loaders, versions, license, side support, gallery, related mods);
 *   2. tag-driven illustrations (mods-lib tagTile, a port of mod_tags.py;
 *      categories with no illustration get the neutral default);
 *   3. curated highlights — hand-written for Lithium only (the design's
 *      LITHIUM dict). Every other mod's highlights are built strictly from
 *      its real fields; nothing is invented.
 * Unknown / inactive / upstream-dead mod -> 404.
 */
type Curated = {
  summaryExtra?: string;
  details?: string[];
  highlights?: [string, string, "phys" | "ai" | "tick"][];
  vanilla?: string;
  sides?: { title: string; text: string; diagram: boolean };
  requires?: string;
  config?: string;
};
/** build_modpage.py LITHIUM — the design's curated layer, Lithium only. */
const CURATED: Record<string, Curated> = {
  "minecraft/lithium": {
    summaryExtra: "It speeds up the systems the game ticks without changing a single vanilla mechanic.",
    details: [
      "Lithium is a general-purpose optimization mod that improves a number of the game’s systems, including physics, mob AI and block ticking.",
      "Its goal is to leave vanilla behaviour completely unchanged, which has even led to it being allowed in official Minecraft speedrunning.",
      "It works on both the client and the server, and either side can run it without the other.",
      "A configuration system lets you disable any individual patch, which helps if another mod conflicts with one.",
    ],
    highlights: [
      ["Game physics", "Entity movement and collisions, handled with less work per tick.", "phys"],
      ["Mob AI", "Pathfinding and behaviour checks, optimized without changing how mobs act.", "ai"],
      ["Block ticking", "The world updates it runs constantly, done more efficiently.", "tick"],
    ],
    vanilla: "Lithium doesn’t change game mechanics, which is why it’s even allowed in official Minecraft speedrunning.",
    sides: { title: "Your players don’t need it", text: "It works on the server alone, so players join with a normal game. It also works on clients if they want it.", diagram: true },
    requires: "Fabric Loader on Fabric. Not even Fabric API is needed.",
    config: "Every patch can be switched off in its config file.",
  },
};

async function modOr404(p: Record<string, string>) {
  const f = await familyOr404(p.family);
  if (!p.slug) notFound();
  const mod = await getCatalogMod(f.family, p.slug);
  // public = active && upstreamOk (getCatalogMod already drops inactive rows)
  if (!mod || !mod.upstreamOk) notFound();
  return { f, mod };
}

/** Same meta description the live mod page builds (real longDescription/description, else real fields). */
function metaDescription(mod: ModDetail) {
  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
  if (raw) {
    const plain = raw.replace(/```[\s\S]*?```/g, " ").replace(/!\[[^\]]*\]\([^)]*\)/g, " ").replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/<[^>]+>/g, " ").replace(/\[\/?[a-z0-9]+[^\]]*\]/gi, " ").replace(/[#>*_`~-]/g, " ").replace(/\s+/g, " ").trim();
    if (plain.length <= 160) return plain;
    const cut = plain.slice(0, 157), sp = cut.lastIndexOf(" ");
    return `${cut.slice(0, sp > 100 ? sp : 157)}…`;
  }
  return `${mod.name} for ${mod.gameFamilyLabel}, verified against ${sourceLabel(mod.source)} — real download counts, supported versions, and a direct download link.`;
}
const images = (mod: ModDetail) => [mod.iconUrl, ...mod.galleryUrls].filter((u): u is string => !!u);

export async function meta(p: Record<string, string>) {
  const { mod } = await modOr404(p);
  const img = mod.galleryUrls[0] ?? mod.iconUrl ?? undefined;
  return {
    title: `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`,
    description: metaDescription(mod),
    crumb: mod.name,
    ...(img ? { image: img } : {}),
  };
}

const bodySource = (s: string): ModBodySource => (s === "modrinth" || s === "thunderstore" || s === "steam_workshop" ? s : "other");

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const { f, mod } = await modOr404(p);
  const cur = CURATED[`${mod.gameFamily}/${mod.slug}`];
  const T = mod.name;
  const src = sourceLabel(mod.source);
  const [related, download, plans, regions, user] = await Promise.all([
    relatedCatalogMods(mod, 8),
    resolveDownloadUrl(mod),
    familyPlans(f.family),
    regionsWithFlags(),
    currentUser(),
  ]);
  const eligible = user ? await getEligibleServersForMod(mod.id) : { loggedIn: false, servers: [] };
  const support = installable(mod.gameFamily, mod.source);
  const { c1, c2 } = palette(mod.category);
  const summary = mod.description || composedDescriptionFor(mod);
  const up = ago(mod.upstreamUpdatedAt);
  const loaders = mod.loaders.map(loaderLabel);
  const latest = mod.gameVersions[mod.gameVersions.length - 1];
  const size = formatBytes(mod.fileBytes);
  const recommended = recommendedPlanFor(mod, plans.tiers.map((t) => ({ id: t.id, name: t.name, ramMB: t.ram * 1024, priceCents: Math.round((t.i ?? t.p) * 100), active: true })));
  const pick = plans.tiers.find((t) => t.id === recommended?.id) ?? plans.cheapest;

  // ── hero ──
  const badges = [mod.verified && '<span class="bv">✓ Verified</span>', mod.featured && '<span class="bf">★ Featured</span>', `<span class="bc">${esc(mod.category)}</span>`].filter(Boolean).join("");
  const stats = [
    dl(mod.downloads) && [dl(mod.downloads)!, "Downloads"],
    up && [up, "Last updated"],
    mod.license && [mod.license, "License"],
    loaders.length && [loaders.slice(0, 3).join(" · "), "Loaders"],
    size && [size, "File size"],
    latest && [latest, "Latest game version"],
    [src, "Source"],
  ].filter(Boolean).slice(0, 4) as [string, string][];
  const actions = [
    `<a class="nxm-btn" href="#add"><span class="nxm-bt">Add to my server<span class="ar">→</span></span></a>`,
    mod.url && btnGlass(mod.url, `Download from ${src}`, true),
  ].filter(Boolean).join("");

  // ── gallery (the mod's own source screenshots; hidden when it has none) ──
  const gallery = mod.galleryUrls.length ? galleryHtml(mod, src) : "";

  // ── about: the source's own long body, else the curated (Lithium) notes ──
  const body = mod.longDescription ? renderModBody(mod.longDescription, bodySource(mod.source), 6000) : null;
  const details = body
    ? `<div class="dtl" id="dtl"><div class="nxm-modbody">${body.html}</div>${body.truncated && mod.url ? `<p><a href="${attr(mod.url)}" target="_blank" rel="noopener noreferrer nofollow ugc">Read the full description on ${esc(src)} →</a></p>` : ""}</div><button type="button" class="dtl-t" id="dtl-t" aria-expanded="false">Read the full description</button>`
    : cur?.details
      ? `<div class="dtl" id="dtl"><ul>${cur.details.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></div><button type="button" class="dtl-t" id="dtl-t" aria-expanded="false">Read the full description</button>`
      : "";
  const aboutLabel = body ? `From ${src}` : cur?.details ? "Curated by NxLabs" : `From ${src}`;

  // ── highlights: curated for Lithium; real fields for every other mod ──
  const hl = highlightsHtml(mod, f, cur, { loaders, latest, size, up });

  // ── side support (Modrinth-style server_side flag) ──
  const sides = sidesFor(mod, src, cur);
  const sidesHtml = sides
    ? `<div class="blk"><div class="blk-h"><h3>${esc(sides.title)}</h3><span class="lay ${cur?.sides ? "cur" : "auto"}">${cur?.sides ? "Curated by NxLabs" : "From source side support"}</span></div><p class="blk-p">${esc(sides.text)}</p>${sides.diagram ? diagram(mod) : ""}</div>`
    : "";

  // ── compatibility + verified-at-source cards ──
  const runsOn = mod.serverSide === "required" ? '<span class="tg ok">Server</span><small>required on the server</small>'
    : mod.serverSide === "optional" ? (cur?.sides?.diagram ? '<span class="tg ok">Server</span><span class="tg ok">Client</span><small>either side alone</small>' : '<span class="tg ok">Server</span><small>optional on the server</small>')
    : mod.serverSide === "unsupported" ? '<span class="tg">Client only</span>' : "";
  const requires = [cur?.requires, mod.appliesToVariant && `A ${loaderLabel(mod.appliesToVariant)} server.`,
    mod.dependencyCount > 0 && `${n(mod.dependencyCount)} other ${mod.dependencyCount === 1 ? "project" : "projects"} alongside it.`].filter(Boolean).join(" ");
  const row = (dt: string, dd: string) => `<div><dt>${dt}</dt><dd>${dd}</dd></div>`;
  const compat = [
    row("Game", esc(mod.gameFamilyLabel)),
    loaders.length && row("Loaders", loaders.map((l) => `<span class="tg">${esc(l)}</span>`).join("")),
    runsOn && row("Runs on", runsOn),
    latest && row("Game versions", `${esc(latest)}${mod.gameVersions.length > 1 ? ` <small>and ${n(mod.gameVersions.length - 1)} earlier</small>` : ""}`),
    requires && row("Requires", esc(requires)),
    size && row("File size", esc(size)),
    cur?.config && row("Configurable", esc(cur.config)),
  ].filter(Boolean).join("");
  const vfy = [
    `<li><span class="vk">✓</span><span><b>${esc(src)}</b><small>${mod.verifiedAt ? `Official listing, checked ${mod.verifiedAt.toISOString().slice(0, 10)}` : "Official listing"}</small></span>${mod.url ? `<a href="${attr(mod.url)}" target="_blank" rel="noopener noreferrer nofollow">Open ↗</a>` : ""}</li>`,
    mod.authorName && `<li><span class="vk">✓</span><span><b>Author</b><small>${esc(mod.authorName)}, as published on ${esc(src)}</small></span></li>`,
    `<li><span class="vk">✓</span><span><b>License</b><small>${esc(mod.license ?? "Not published by the source")}</small></span><em>${mod.paid ? "Paid" : "Free"}</em></li>`,
  ].filter(Boolean).join("");

  // ── add to a server: the real flow (portal installMod) or a real deploy ──
  const add = addPanel(mod, f, plans, pick?.id ?? null, regions, eligible, support);

  // ── FAQ, generated from the mod's own source data ──
  const faq = [
    sides && [`Do my players need to install ${T}?`, sides.text],
    loaders.length && [`Which loaders does it support?`, `${loaders.join(" and ")}.${cur?.requires ? ` ${cur.requires}` : ""}`],
    [`Is it free?`, mod.paid ? `No. ${T} is a paid listing on ${src}.` : `Yes. ${T} is free to download from ${src}.${mod.license ? ` Its license is ${mod.license}.` : ""}`],
    [`How do I add it to my Nxeon server?`, support.ok
      ? `Use “Add to a server” on this page, or open NxLabs from your dashboard. We install it, restart your server and switch it on.`
      : `${support.message.replace(/ — /g, ": ")} Download ${T} from ${src} and upload it to your Nxeon ${mod.gameFamilyLabel} server in Files.`],
  ].filter(Boolean) as [string, string][];

  // ── final CTA ──
  const final = pick
    ? `<p>Deploy in about a minute from ${tierPrice(plans.cheapest!)} a month, then ${support.ok ? `add ${esc(T)} in one click` : `upload ${esc(T)} in Files`}.</p><div class="final-ctas">${btnDeploy(deployHref({ service: "game", gameFamily: f.family, gamePlanId: pick.id }), `Deploy a ${mod.gameFamilyLabel} server`)}${btnGlass(gameHref(f.family), `More ${mod.gameFamilyLabel} mods`)}</div>`
    : `<p>Free to download from ${esc(src)}.</p><div class="final-ctas">${mod.url ? btnDeploy(mod.url, `Download from ${src}`).replace("nxm-btn au-hov", "nxm-btn") : ""}${btnGlass(gameHref(f.family), `More ${mod.gameFamilyLabel} mods`)}</div>`;

  const deployMap: Record<string, string> = {};
  for (const t of plans.tiers) for (const r of regions.length ? regions : [{ code: "" }]) {
    deployMap[`${t.id}|${r.code}`] = deployHref({ service: "game", gameFamily: f.family, gamePlanId: t.id, region: r.code || undefined });
  }

  return {
    slots: {
      "art.c1": c1, "art.c2": c2,
      "game.name": mod.gameFamilyLabel,
      "game.href": gameHref(f.family),
      "browse.href": browseHref(f.family, { sort: "downloads" }),
      "mod.name": T,
      "mod.ic:html": mod.iconUrl ? iconOr(mod, 2) : `<i>${esc(T.slice(0, 2))}</i>`,
      "mod.dmic:html": iconOr(mod, 2),
      "badges:html": badges,
      "by:html": mod.authorName ? `by <b>${esc(mod.authorName)}</b> · for ${esc(mod.gameFamilyLabel)}` : `for ${esc(mod.gameFamilyLabel)}`,
      "summary": summary + (cur?.summaryExtra ? ` ${cur.summaryExtra}` : ""),
      "summaryShort": summary,
      "stats:html": stats.map(([b, s]) => `<div><b>${esc(b)}</b><small>${esc(s)}</small></div>`).join(""),
      "actions:html": actions,
      "gallery:html": gallery,
      "about.label": aboutLabel,
      "details:html": details,
      "highlights:html": hl,
      "tags:html": tagTile(mod.category, mod.source),
      "sides:html": sidesHtml,
      "vanilla:html": cur?.vanilla ? `<div class="blk vv"><span class="vv-ic"><span data-au-icon="check" data-grad></span></span><div><b>Vanilla stays vanilla.</b><p>${esc(cur.vanilla)}</p></div></div>` : "",
      "compat:html": compat,
      "verified:html": vfy,
      "add:html": add,
      "related:html": related.length ? relatedHtml(mod, related) : "",
      "faq:html": faq.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("\n  "),
      "final:html": final,
    },
    data: { deploy: deployMap },
    crumb: T,
    jsonLd: [softwareLd(mod, download?.url ?? null)],
  };
}

function galleryHtml(mod: ModDetail, src: string) {
  const g = mod.galleryUrls;
  const thumbs = g.map((u, i) => `<button type="button" class="gth${i === 0 ? " on" : ""}" data-i="${i}" aria-label="Screenshot ${i + 1}"><img src="${attr(u)}" alt="" loading="lazy" referrerpolicy="no-referrer" width="320" height="180"></button>`).join("");
  return `<section class="section gal" id="gallery" aria-labelledby="gl-title" style="padding-top:10px"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="gl-title">Gallery</h2></div><span class="gal-src">From ${esc(src)}</span></div>
  <div class="gal-grid"><button type="button" class="gal-main" id="gal-main" aria-label="Open screenshot"><img id="gal-img" src="${attr(g[0])}" alt="${attr(mod.name)} screenshot 1" referrerpolicy="no-referrer" width="1280" height="720"><span class="gal-zoom">⤢ View full size</span></button>${g.length > 1 ? `<div class="gal-th">${thumbs}</div>` : `<div class="gal-th" hidden>${thumbs}</div>`}</div>
</div></section>
<div class="lbx" id="lbx" hidden role="dialog" aria-modal="true" aria-label="Screenshot viewer"><button type="button" class="lbx-x" aria-label="Close">×</button><button type="button" class="lbx-p" aria-label="Previous">‹</button><img id="lbx-img" alt="" referrerpolicy="no-referrer"><button type="button" class="lbx-n" aria-label="Next">›</button><p class="lbx-c" id="lbx-c"></p></div>`;
}

const ILLS: Record<string, string> = {
  phys: '<div class="wd-ill wd-phys" aria-hidden="true"><i></i><i></i><i></i></div>',
  ai: '<div class="wd-ill wd-ai" aria-hidden="true"><i></i><i></i><i></i><i></i></div>',
  tick: `<div class="wd-ill wd-tick" aria-hidden="true">${"<i></i>".repeat(16)}</div>`,
};

function highlightsHtml(mod: ModDetail, f: Family, cur: Curated | undefined, x: { loaders: string[]; latest?: string; size: string | null; up: string | null }) {
  let items: [string, string, string][];
  let label: string, cls: string;
  if (cur?.highlights) {
    items = cur.highlights; label = "Curated by NxLabs"; cls = "cur";
  } else {
    const v = mod.gameVersions.length;
    const cand: ([string, string] | null)[] = [
      x.latest ? ["Game versions", v > 1 ? `Supports ${n(v)} ${f.label} versions, the newest being ${x.latest}.` : `Built for ${f.label} ${x.latest}.`] : null,
      x.loaders.length ? ["Loaders", `Runs on ${x.loaders.join(", ").replace(/, ([^,]*)$/, " and $1")}.`] : null,
      x.size || mod.verifiedAt ? ["Footprint", `${x.size ? `A ${x.size} download, ` : ""}rated a ${mod.impact} load on a server.${mod.impactNote ? ` ${mod.impactNote}` : ""}`.replace(/^rated/, "Rated")] : null,
      mod.dependencyCount > 0 ? ["Dependencies", `Needs ${n(mod.dependencyCount)} other ${mod.dependencyCount === 1 ? "project" : "projects"} installed alongside it.`] : null,
      mod.license ? ["License", `Published under ${mod.license}.`] : null,
      x.up ? ["Last update", `Its author last shipped an update ${x.up}.`] : null,
    ];
    const kinds = ["tick", "ai", "phys"];
    items = cand.filter((c): c is [string, string] => !!c).slice(0, 3).map((c, i) => [c[0], c[1], kinds[i]]);
    label = "From source data"; cls = "auto";
    if (items.length < 2) return "";
  }
  return `<div class="blk"><div class="blk-h"><h3>Highlights</h3><span class="lay ${cls}">${label}</span></div><div class="wd3">${items.map(([t, d, k]) => `<article class="wd">${ILLS[k]}<h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join("")}</div></div>`;
}

/** mod_tags.py sides(), from the one side flag the catalogue carries (server_side). */
function sidesFor(mod: ModDetail, src: string, cur?: Curated): { title: string; text: string; diagram: boolean } | null {
  if (cur?.sides) return cur.sides;
  if (mod.serverSide === "required") return { title: "Runs on your server", text: `${src} lists ${mod.name} as required on the server. Check its ${src} page to see whether players need it too.`, diagram: false };
  if (mod.serverSide === "optional") return { title: "Works on a server", text: `${src} lists server-side support for ${mod.name} as optional: it can run on a server, but isn’t required there.`, diagram: false };
  if (mod.serverSide === "unsupported") return { title: "Client-side mod", text: `${src} lists ${mod.name} as not supported on servers. It runs in players’ own games, not on your server.`, diagram: false };
  return null;
}

function diagram(mod: ModDetail) {
  const T = mod.name;
  return `<div class="sdg" aria-hidden="true"><div class="sdg-srv"><span class="dm-l" style="--c1:#3FD89A;--c2:#3EDCF2">${esc(T.slice(0, 2))}</span><b>Your server</b><small>${esc(T)} installed</small></div><svg class="sdg-l" viewBox="0 0 300 240" preserveAspectRatio="none"><path d="M0 120 C 120 120 160 30 300 30"/><path d="M0 120 H300"/><path d="M0 120 C 120 120 160 210 300 210"/></svg><div class="sdg-cl">${["Alex", "Sam", "Riley"].map((x) => `<div><span>${x[0]}</span><b>${x}</b><em>Vanilla client ✓</em></div>`).join("")}</div></div>`;
}

function addPanel(mod: ModDetail, f: Family, plans: FamilyPlans, pickId: string | null,
  regions: { code: string; label: string; flag: string }[], eligible: { loggedIn: boolean; servers: { id: string; hostname: string; label: string | null; status: string }[] },
  support: { ok: true } | { ok: false; message: string }) {
  const T = mod.name, G = mod.gameFamilyLabel;
  const hasNew = plans.tiers.length > 0;
  const portal = portalModHref(mod);
  let mine: string;
  if (!support.ok) {
    mine = `<p class="asv-warn">${esc(support.message)}${mod.url ? ` <a href="${attr(mod.url)}" target="_blank" rel="noopener noreferrer nofollow">Get ${esc(T)} from ${esc(sourceLabel(mod.source))} ↗</a>` : ""}</p>`;
  } else if (!eligible.loggedIn) {
    mine = `<p class="asv-warn"><a href="/login?next=${attr(encodeURIComponent(portal))}">Log in</a> to add ${esc(T)} to one of your ${esc(G)} servers.${hasNew ? ` No server yet? <a href="#" data-go-new>Deploy one →</a>` : ""}</p>`;
  } else if (!eligible.servers.length) {
    mine = `<p class="asv-warn">You don’t have a ${esc(G)} server that can run ${esc(T)} yet.${hasNew ? ` <a href="#" data-go-new>Deploy one →</a>` : ""}</p>`;
  } else {
    const rows = eligible.servers.map((s, i) => {
      const name = s.label || s.hostname;
      return `<label class="asv"><input type="radio" name="asv" value="${attr(s.id)}" data-label="${attr(name)}"${i === 0 ? " checked" : ""} data-ok="1"><span class="asv-dot ok"></span><span class="asv-t"><b>${esc(name)}</b><small>${esc(s.hostname)} · ${esc(s.status.toLowerCase())}</small></span><span class="asv-b ok">Compatible</span></label>`;
    }).join("");
    const first = eligible.servers[0].label || eligible.servers[0].hostname;
    mine = `<div class="asvs">${rows}</div>
      <div class="adp-perks"><span><span data-au-icon="bolt" data-grad></span>One click</span><span><span data-au-icon="refresh" data-grad></span>Auto restart</span><span><span data-au-icon="backup" data-grad></span>Daily restore points</span></div>
      <a class="adp-go" id="adp-go" href="${attr(portal)}" data-t="${attr(`Add ${T} to {s}`)}"><span class="adp-go-t">Add ${esc(T)} to ${esc(first)}</span></a>`;
  }
  const pick = plans.tiers.find((t) => t.id === pickId) ?? plans.tiers[0];
  const newPane = hasNew
    ? `<div class="adp-pane" data-p="new" hidden>
      <p class="adp-new-k">Get a ${esc(G)} server, then ${support.ok ? `add ${esc(T)} in one click` : `upload ${esc(T)} in Files`}.</p>
      <div class="nsz" role="group" aria-label="Server size">${plans.tiers.map((t) => `<button type="button" aria-pressed="${t.id === pick.id}" data-id="${attr(t.id)}" data-p="${attr(tierPrice(t))}">${tierRam(t)}<small>${tierPrice(t)}</small></button>`).join("")}</div>
      ${regions.length > 1 ? `<div class="nsz nrg" role="group" aria-label="Region">${regions.map((r, i) => `<button type="button" aria-pressed="${i === 0}" data-r="${attr(r.code)}">${r.flag ? `<span class="flag flag-sm flag-${attr(r.flag)}"></span>` : ""}${esc(r.label)}</button>`).join("")}</div>` : ""}
      <a class="adp-go adp-deploy" href="${attr(deployHref({ service: "game", gameFamily: f.family, gamePlanId: pick.id, region: regions[0]?.code }))}"><span class="adp-go-t">Deploy a ${esc(G)} server · <em id="nsz-p">${tierPrice(pick)}</em>/mo</span></a>
      ${pick.i != null ? `<p class="adp-fine">Intro price for the ${introSpan(pick.it)}, then ${usd(Math.round(pick.p * 100))}/mo.</p>` : ""}
      <p class="adp-fine">Live in about a minute. DDoS protection and daily restore points included.</p>
    </div>`
    : "";
  return `<aside class="adp" id="add" aria-label="Add ${attr(T)} to a server"><div class="adp-in">
    <div class="adp-top"><span class="dm-l adp-ic" style="--c1:#3FD89A;--c2:#3EDCF2">${iconOr(mod, 2)}</span><div><b>Add ${esc(T)} to a server</b><small>${support.ok ? "One click. We install, restart and switch it on." : `${esc(G)} mods are installed by hand, in Files.`}</small></div></div>
    ${hasNew ? `<div class="au-seg adp-tabs" role="tablist"><button type="button" role="tab" aria-pressed="true" data-t="mine">My servers</button><button type="button" role="tab" aria-pressed="false" data-t="new">New server</button></div>` : ""}
    <div class="adp-pane" data-p="mine">
      ${mine}
    </div>
    ${newPane}
  </div></aside>`;
}

function relatedHtml(mod: ModDetail, related: Awaited<ReturnType<typeof relatedCatalogMods>>) {
  return `<section class="section mrow-s" id="related" aria-labelledby="rl-title" style="padding-top:0"><div class="container">
  <div class="mrow-h"><div><h2 class="h2" id="rl-title">More like ${esc(mod.name)}</h2><p class="lede">Other ${esc(mod.gameFamilyLabel)} mods, same category first, ranked by real downloads.</p></div><div class="mrow-c"><a class="va" href="${attr(browseHref(mod.gameFamily, { sort: "downloads" }))}">View all<span aria-hidden="true">→</span></a><button type="button" class="cb prev" aria-label="Previous">‹</button><button type="button" class="cb next" aria-label="Next">›</button></div></div>
  <div class="mrow" tabindex="0" aria-label="Related mods">${related.map((m, i) => xmodCard(m, `r${i}`)).join("")}</div>
</div></section>`;
}

/** Same SoftwareApplication the live mod page emits — every field real or omitted. */
function softwareLd(mod: ModDetail, downloadUrl: string | null) {
  const imgs = images(mod);
  return {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: mod.name,
    applicationCategory: "GameApplication",
    operatingSystem: mod.gameFamilyLabel,
    description: mod.description || `${mod.name} for ${mod.gameFamilyLabel}.`,
    url: `${process.env.APP_URL ?? "https://nxeon.cloud"}/mods/${encodeURIComponent(mod.gameFamily)}/${encodeURIComponent(mod.slug)}`,
    datePublished: mod.createdAt,
    ...(mod.upstreamUpdatedAt ? { dateModified: mod.upstreamUpdatedAt } : {}),
    ...(mod.authorName ? { author: { "@type": "Person", name: mod.authorName } } : {}),
    ...(imgs.length ? { image: imgs } : {}),
    ...(downloadUrl ? { downloadUrl } : {}),
    ...(mod.license ? { license: mod.license } : {}),
    ...(mod.gameVersions.length ? { softwareVersion: undefined, softwareRequirements: `${mod.gameFamilyLabel} ${mod.gameVersions[mod.gameVersions.length - 1]}` } : {}),
    ...(!mod.paid ? { offers: { "@type": "Offer", price: "0", priceCurrency: "USD" } } : {}),
    ...(mod.ratingCount > 0 && mod.avgRating != null
      ? { aggregateRating: { "@type": "AggregateRating", ratingValue: mod.avgRating.toFixed(1), reviewCount: mod.ratingCount } }
      : {}),
  };
}

// keep the links helpers referenced for the template's own at()/modHref use
void at; void modHref;

