def swap_buttons(h: str):
    """Design buttons -> the library's hierarchy (IDENTITY-SPEC §3 Buttons):
    primary/deploy -> .nxm-btn (rocket on deploy/buy), glass -> .nxm-glassbtn,
    ghost -> .nxm-ghost. Labels go in .nxm-bt so scripts can rewrite them
    without wiping the icon. Other classes are kept (scripts query them)."""
    n = {"primary": 0, "glass": 0, "ghost": 0}
    def rep(m):
        tag, attrs, inner = m.group(1), m.group(2), m.group(3)
        cm = re.search(r'\bclass="([^"]*)"', attrs)
        if not cm or "${" in cm.group(1): return m.group(0)
        c = cm.group(1).split()
        if "au-btn" in c:
            kind = "glass" if "au-btn--glass" in c else "ghost" if "au-btn--ghost" in c else "primary"
            drop = {"au-btn", "au-btn--glass", "au-btn--ghost", "sm"}
            small = "sm" in c
        elif "btn" in c and ({"btn-primary", "btn-grad", "btn-ghost"} & set(c)):
            kind = "glass" if "btn-ghost" in c else "primary"
            drop = {"btn", "btn-primary", "btn-grad", "btn-ghost", "btn-sm"}
            small = "btn-sm" in c
        else:
            return m.group(0)
        keep = [x for x in c if x not in drop]
        had_arrow = bool(re.search(r'<span class="ar"[^>]*>(?:→|&rarr;)</span>', inner))
        inner = re.sub(r'\s*<span class="ar"[^>]*>(?:→|&rarr;)</span>', "", inner)
        text = re.sub(r"<[^>]+>", "", inner).strip().lower()
        base = {"primary": "nxm-btn", "glass": "nxm-glassbtn", "ghost": "nxm-ghost"}[kind]
        cls = [base] + (["nxm-sm"] if small else []) + keep
        lead, tail = "", ""
        if kind == "primary":
            if text.startswith(DEPLOY_WORDS):
                lead = ROCKET; cls.append("au-hov")
            if had_arrow or (not small and "→" not in inner and "&rarr;" not in inner and "<svg" not in inner):
                tail = ARW
        elif had_arrow:
            tail = ARW
        n[kind] += 1
        attrs = attrs.replace(cm.group(0), f'class="{" ".join(cls)}"')
        return f'<{tag}{attrs}>{lead}<span class="nxm-bt">{inner}</span>{tail}</{tag}>'
    out = re.sub(r"<(a|button)\b([^>]*)>([\s\S]*?)</\1>", rep, h)
    return out, n

