const list = (xs: string[]) => (xs.length < 2 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);

async function data() {
  const [fams, tiers, bySource, total] = await Promise.all([
    families(),
    gameTiers(),
    db.gameMod.groupBy({ by: ["gameFamily", "source"], where: { active: true, upstreamOk: true }, _count: true }),
    Promise.resolve(0),
  ]);
  const count = new Map(fams.map((f) => [f.family, f.count]));
  const price = (t: GameTier) => t.i ?? t.p;
  const cheapest = new Map<string, GameTier>();
  for (const t of tiers) { const c = cheapest.get(t.family); if (!c || price(t) < price(c)) cheapest.set(t.family, t); }
  if (!cheapest.size) throw new Error("nxm game-servers-mods: no active game plans");

  const oneClick = new Map<string, number>(), wsOnly = new Map<string, boolean>();
  for (const r of bySource) {
    if (!installSupport(r.gameFamily, r.source).ok) continue;
    oneClick.set(r.gameFamily, (oneClick.get(r.gameFamily) ?? 0) + r._count);
    wsOnly.set(r.gameFamily, (wsOnly.get(r.gameFamily) ?? true) && r.source === "steam_workshop");
  }
  const rows: Row[] = [...cheapest.entries()].map(([family, t]) => ({
    family, label: gameLabel(family), mods: count.get(family) ?? 0, oneClick: oneClick.get(family) ?? 0,
    workshopOneClick: wsOnly.get(family) ?? false, cheapest: t, poster: gameArt(family).poster,
  })).sort((a, b) => b.oneClick - a.oneClick || b.mods - a.mods || a.label.localeCompare(b.label));

  const catalogueTotal = fams.reduce((s, f) => s + f.count, 0);
  void total;
  const oneClickGames = rows.filter((r) => r.oneClick > 0);
  const workshopGames = oneClickGames.filter((r) => r.workshopOneClick);
  const from = rows.reduce((a, b) => (price(a.cheapest) <= price(b.cheapest) ? a : b)).cheapest;
  return { rows, catalogueTotal, oneClickGames, workshopGames, from };
}

export async function meta(_p: Record<string, string>) {
  const d = await data();
  const oc = d.oneClickGames.slice(0, 4).map((r) => r.label);
  return {
    title: "Mod Support — One-Click Mod Store Plus Full File Access",
    description: `One-click mods from NxLabs for ${list(oc)}${d.oneClickGames.length > 4 ? " and more" : ""}, plus full SFTP, file manager and console access on all ${d.rows.length} Nxeon game servers. No locked-down panel, no mod limits.`,
    crumb: "Mod support",
  };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const [d, top, dlTotal] = await Promise.all([data(), listTopDownloadedMods(undefined, 12), totalDownloadsFor()]);
  const hosting = hostingRoutes();
  const oc = d.oneClickGames.map((r) => r.label);

  const rowsHtml = d.rows.map((r) => {
    const art = r.poster ? `<img src="${attr(r.poster)}" alt="" loading="lazy" width="40" height="40">` : `<span class="gsm-m">${esc(mono2(r.label))}</span>`;
    const host = hosting.get(r.family);
    const name = host ? `<a href="${attr(at(host))}">${esc(r.label)}</a>` : `<b>${esc(r.label)}</b>`;
    const how = r.oneClick > 0
      ? `<span class="gsm-b ${r.workshopOneClick ? "ws" : "ok"}">✓ One click${r.workshopOneClick ? " (Steam Workshop)" : ""}</span><small>${n(r.oneClick)} ${r.oneClick === 1 ? "mod" : "mods"} ready to add · SFTP for the rest</small>`
      : `<span class="gsm-b">Upload in Files</span><small>SFTP, file manager and console</small>`;
    const links = [
      r.mods > 0 && `<a href="${attr(gameHref(r.family))}">Browse mods</a>`,
      `<a href="${attr(deployHref({ service: "game", gameFamily: r.family, gamePlanId: r.cheapest.id }))}">Deploy →</a>`,
    ].filter(Boolean).join("");
    return `<tr data-n="${attr(r.label.toLowerCase())}"><td data-l="Game"><div class="gsm-g">${art}${name}</div></td><td data-l="Mods in NxLabs">${r.mods ? `<b>${n(r.mods)}</b>` : `<small>None listed yet</small>`}</td><td data-l="How mods install">${how}</td><td data-l="Server from"><span class="gsm-p">${tierPrice(r.cheapest)}</span><small>/month</small></td><td><div class="gsm-a">${links}</div></td></tr>`;
  }).join("");

  const popular = top.length
    ? `<section class="section mrow-s" id="popular" aria-labelledby="po-title" style="padding-top:0"><div class="container">
  <div class="mrow-h"><div><h2 class="h2" id="po-title">What servers are running</h2><p class="lede">The most downloaded mods in NxLabs, by real download counts from each mod’s own source.</p></div><div class="mrow-c"><a class="va" href="${attr(hubHref({ sort: "downloads" }))}#results">View all<span aria-hidden="true">→</span></a><button type="button" class="cb prev" aria-label="Previous">‹</button><button type="button" class="cb next" aria-label="Next">›</button></div></div>
  <div class="mrow" tabindex="0" aria-label="Most downloaded mods">${top.map((m, i) => xmodCard(m, `p${i}`, `<span class="mc-rank${i < 3 ? " g" : ""}">#${i + 1}</span>`, { showGame: true })).join("")}</div>
</div></section>`
    : "";

  const deployAny = at("/game-servers");
  const ws = d.workshopGames.map((r) => r.label);
  return {
    slots: {
      "hero.sub": `${n(d.catalogueTotal)} mods in NxLabs, ${d.oneClickGames.length} ${d.oneClickGames.length === 1 ? "game" : "games"} where they install in one click, and SFTP, a file manager and a live console on all ${d.rows.length} games we host.`,
      "hero.ctas:html": btnDeploy(deployAny, "Deploy a game server") + btnGlass(hubHref(), "Browse NxLabs mods"),
      "mods.totalRaw": String(d.catalogueTotal),
      "oneclick.gamesRaw": String(d.oneClickGames.length),
      "games.hostedRaw": String(d.rows.length),
      "games.hosted": String(d.rows.length),
      "oneclick.chips:html": d.oneClickGames.map((r) => `<span>${esc(r.label)}</span>`).join(""),
      "oneclick.body": `For ${list(oc)}, pick a mod in NxLabs and press Add to my server: we install it and restart your server for you.`,
      "games.lede": `All ${d.rows.length} games we host, with the real number of NxLabs mods for each and how they install.`,
      "games.rows:html": rowsHtml,
      "popular:html": popular,
      "faq.oneclick": `For ${list(oc)}, yes: NxLabs can place those mods for you, so you pick one and add it in one click. For every other game you install mods the honest way: upload over SFTP or the file manager, then restart. We don’t fake a magic universal installer.`,
      "faq.workshop": ws.length
        ? `For ${list(ws)}, NxLabs adds Workshop items for you: it writes the Workshop ID into the server’s config and the game downloads the content from Steam on restart. For other games with official Workshop support, reference Workshop IDs in your server config the standard way and they mount on restart.`
        : "Games with official Workshop support work the standard way: reference Workshop IDs in your server config and they mount on restart.",
      "final.sub": `Game servers from ${tierPrice(d.from)} a month, with ${n(d.catalogueTotal)} NxLabs mods and ${dlTotal ? "real download counts from every source" : "full file access"} a click away.`,
      "final.ctas:html": btnDeploy(deployAny, "Deploy a game server") + btnGlass(hubHref(), "Browse NxLabs mods"),
    },
    data: {},
    crumb: "Mod support",
    jsonLd: [
      productLd("Nxeon Game Server Hosting — Full Mod & File Access",
        `Every Nxeon game server ships with full SFTP, an in-dashboard file manager and live console access. ${list(oc)} also get one-click installs from NxLabs.`,
        "/game-servers/mods", d.rows.map((r) => ({ name: `${r.label} server hosting`, price: r.cheapest.i ?? r.cheapest.p }))),
      ...(top.length ? [itemListLd("Most downloaded mods on NxLabs", top)] : []),
    ],
  };
}

