import "server-only";
import { unstable_cache } from "next/cache";
import { Prisma, type GameMod } from "@prisma/client";
import { db } from "@/lib/db";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import type { ModSummary } from "@/lib/mods-catalog";

/**
 * NxLabs taxonomy for the new marketing site: one clear category per mod,
 * computed at query time (no DB writes) from the mod's REAL source data.
 *
 * GameMod.category is one free-text value per mod in each source's own words
 * ("Workshop", "content", "tweaks", "Creatures", "Admin & Permissions", ...).
 * The classification, in order:
 *   1. the source category, when it already says what the mod is
 *      ("Performance", "Economy", "Creatures", "Weapons" ...) -> DIRECT;
 *   2. otherwise (generic buckets like "Workshop", "Mod", "content", or an
 *      unmapped niche one) keywords in the mod's NAME, then in the first 400
 *      characters of its DESCRIPTION (whole words only) -> RULES, first hit
 *      wins, most specific rules first;
 *   3. otherwise a few broad source buckets fall back (FALLBACK), and anything
 *      left is "other" — never a guess.
 * The same rules run in SQL (filters, counts) and in JS (card labels, mod
 * pages), so a filter and the label it shows always agree.
 */
export type TaxKey =
  | "performance" | "library" | "admin" | "economy" | "worldgen" | "maps" | "items" | "vehicles"
  | "cosmetics" | "qol" | "social" | "mobs" | "tech" | "modes" | "building" | "gameplay";

export type TaxCat = {
  key: TaxKey; label: string; desc: string;
  /** tile illustration (mod_tags.py kinds + NxLabs extensions) */ ill: string;
  /** card banner illustration (mods_ui.py ILL + extensions) */ card: string;
  /** Aurora icon for small tiles */ icon: string;
  c1: string; c2: string;
};

export const TAXONOMY: TaxCat[] = [
  { key: "performance", label: "Performance", desc: "Makes the game or server run faster or lighter without changing how it plays.", ill: "tick", card: "perf", icon: "bolt", c1: "#3FD89A", c2: "#3EDCF2" },
  { key: "library", label: "Libraries & compatibility", desc: "Foundations and fixes other mods build on. Usually installed because something else needs it.", ill: "nodes", card: "core", icon: "cpu", c1: "#6F8DFF", c2: "#B98CFF" },
  { key: "admin", label: "Admin & protection", desc: "Permissions, moderation, anti-cheat and land protection for the people running the server.", ill: "shield", card: "shield", icon: "shield", c1: "#FF9A5C", c2: "#FF5FA8" },
  { key: "economy", label: "Economy & shops", desc: "Currencies, shops, trading and rewards.", ill: "coin", card: "coin", icon: "card", c1: "#FFD27A", c2: "#FF9A5C" },
  { key: "worldgen", label: "World generation", desc: "Changes or adds to how new terrain, biomes and structures are created.", ill: "terrain", card: "wave", icon: "globe", c1: "#3FD89A", c2: "#4E8DFF" },
  { key: "maps", label: "Maps & scenarios", desc: "Custom maps, arenas and scenarios to play on.", ill: "pin", card: "pin", icon: "globe", c1: "#3EDCF2", c2: "#7B5CFF" },
  { key: "items", label: "Weapons, items & crafting", desc: "New weapons, gear, items and the recipes to make them.", ill: "blade", card: "blade", icon: "spark", c1: "#FF6FA8", c2: "#B98CFF" },
  { key: "vehicles", label: "Vehicles & ships", desc: "Cars, boats, aircraft, ships and other things to drive or fly.", ill: "car", card: "car", icon: "rocket", c1: "#4E8DFF", c2: "#3EDCF2" },
  { key: "cosmetics", label: "Cosmetics, visuals & audio", desc: "Skins, textures, shaders, models and sound — how the game looks and sounds.", ill: "brush", card: "brush", icon: "spark", c1: "#E04BD6", c2: "#7B3AF5" },
  { key: "qol", label: "Quality of life & UI", desc: "Small conveniences, tweaks and interface improvements players notice straight away.", ill: "gear", card: "gear", icon: "check", c1: "#FFB36B", c2: "#FF6FA8" },
  { key: "social", label: "Chat & community", desc: "Chat, voice, Discord, clans and other community features.", ill: "chat", card: "chat", icon: "users", c1: "#6FB8FF", c2: "#9B6BFF" },
  { key: "mobs", label: "Creatures & NPCs", desc: "Adds or changes creatures, NPCs and how they behave.", ill: "path", card: "paw", icon: "spark", c1: "#E04BD6", c2: "#FF6FA8" },
  { key: "tech", label: "Technology & automation", desc: "Machines, power, logistics and automation.", ill: "circuit", card: "circuit", icon: "terminal", c1: "#3EDCF2", c2: "#4E6BFF" },
  { key: "modes", label: "Game modes & minigames", desc: "Game modes, minigames and competitive formats for your server.", ill: "target", card: "target", icon: "game", c1: "#E04BD6", c2: "#7B3AF5" },
  { key: "building", label: "Building & decoration", desc: "Blocks, furniture, decorations and building tools.", ill: "cube", card: "cube", icon: "database", c1: "#FFD27A", c2: "#3FD89A" },
  { key: "gameplay", label: "Gameplay & overhauls", desc: "New mechanics, content and overhauls that change how the game plays.", ill: "wave", card: "wave", icon: "game", c1: "#3EDCF2", c2: "#4E8DFF" },
];
export const TAX: Record<string, TaxCat> = Object.fromEntries(TAXONOMY.map((t) => [t.key, t]));
export const isTaxKey = (k: string): k is TaxKey => k in TAX;
export const OTHER = { key: "other", label: "Other", c1: "#6F8DFF", c2: "#9B6BFF", card: "core" } as const;

/** 1. source categories that already say what the mod is (lower-cased, trimmed). */
const DIRECT: Record<TaxKey, string[]> = {
  performance: ["performance", "optimization", "optimisation", "optimizations"],
  library: ["library", "library / dependency", "dependency", "core", "api", "libraries", "compatibility", "cross-play", "patch", "fix", "hotfix", "harmony patching", "code", "counterstrikesharp"],
  admin: ["admin", "admin & permissions", "admin tool", "protection", "server-specific"],
  economy: ["economy"],
  worldgen: ["worldgen", "world", "world generation", "structures", "flora", "grass", "underground"],
  maps: ["map", "custom theater", "scenarios"],
  items: ["items", "item", "weapons", "armor", "food", "crafting", "loot", "smithing", "metal", "drink", "alcohol", "resin", "fuel", "collectables"],
  vehicles: ["boat", "transportation", "mount"],
  cosmetics: ["cosmetics", "skin", "skins (tos risk)", "visual", "graphics", "texture pack", "shaders", "fashion", "clothing", "playermodel", "audio", "music", "bell", "symphony"],
  qol: ["qol", "quality of life", "gather & qol", "tweaks", "tweak", "utility", "utilities", "tools", "external tool", "user experience", "accessibility", "simplification", "hud", "localizations", "language", "translation", "teleport"],
  social: ["social", "chat", "chat & discord", "discord", "clans & social", "community", "roleplay"],
  mobs: ["mobs", "creatures", "animals", "npc", "npcs", "entity logic(ai)", "pets", "villagers", "dragons"],
  tech: ["technology", "mechanic", "mechanics", "automation"],
  modes: ["minigames", "minigame", "game mode", "gun game & 1v1", "retakes", "surf/kz/bhop", "match & scrim", "practice", "pve & events", "mutator", "ranks & stats"],
  building: ["building", "furniture", "decoration", "blockset", "chisel", "object", "woodworking"],
  gameplay: ["gameplay", "overhaul", "total conversion", "mod-packs", "difficulty", "realism", "hardcore", "immersion", "immersive", "classes", "combat", "farming", "magic", "fantasy", "travel & exploration", "cheat", "fun"],
};
/** 2. whole-word keywords, most specific first (checked on the name, then the description). */
const RULES: [TaxKey, string][] = [
  ["performance", "performance|optimi[sz]ation|optimi[sz]es?|optimi[sz]ed|fps|lag|tps|ferritecore|lithium|modernfix"],
  ["library", "library|libraries|api|framework|dependency|dependencies|lib|mod ?loader|compat|compatibility|compatibility patch|bepinex|harmony|ue4ss|metamod|oxide"],
  ["admin", "admin|admins|administration|permissions?|moderation|ban|bans|kick|anti-?cheat|vanish|grief|griefing|land ?claims?|claims?|whitelist|logging"],
  ["economy", "economy|shops?|currency|money|dosh|trader|traders|trading|market|marketplace|bank|auction|coins?"],
  ["vehicles", "vehicles?|cars?|trucks?|ships?|boats?|planes?|aircraft|helicopters?|heli|tanks?|jets?|trains?|rovers?|spaceships?|drones?|bikes?|motorcycles?|hilux|lada|jeep|suv|submarines?|sub"],
  ["maps", "maps?|arena|scenario|scenarios|island|(gm|ttt|rp|de|cs|surf|ze|zs|kz|bhop|jb|mg|dr|kf|zm|ph|ba)_\\w+|kf-\\w+"],
  ["mobs", "mobs?|creatures?|animals?|npcs?|zombies?|monsters?|bosses|boss|pets?|dinos?|dinosaurs?|wildlife|enemies|enemy|villagers?|dragons?|fleshpound"],
  ["items", "weapons?|guns?|rifles?|pistols?|shotguns?|swords?|armou?r|items?|loot|crafting|recipes?|swep|sweps|ammo|pickaxes?|tools?|backpacks?|suits?|knife|knives|bows?|arccw|tfa|m9k"],
  ["tech", "machines?|automation|conveyors?|power|electric|electricity|generators?|reactors?|factory|logistics?|pipes?|circuits?|belts?|industrial|industry|programs?|ic10|scripts?|turrets?|filtration|silos?"],
  ["modes", "game ?modes?|gamemodes?|minigames?|deathmatch|prop ?hunt|ttt|darkrp|murder|battle ?royale|bed ?wars|hide ?and ?seek|pvp|pve|jailbreak|deathrun|retakes|surf|capture the flag|ctf"],
  ["cosmetics", "skins?|textures?|retextures?|reskins?|shaders?|playermodels?|player ?models?|cosmetics?|clothes|clothing|outfits?|hair|hd|sounds?|music|audio|voices?|voice ?pack|announcer|waifu|anime"],
  ["social", "chat|discord|voice ?chat|clans?|party|friends|roleplay|rp|spectate|radio"],
  ["building", "building|buildings|build|furniture|decor|decorations?|decorative|blocks?|prefabs?|walls?|doors?|interior|material ?swapper"],
  ["worldgen", "worldgen|biomes?|terrain|structures?|ruins|dungeons?|world ?generation|caves?|villages?|vegetation|trees"],
  ["qol", "qol|quality of life|tweaks?|utility|utilities|convenience|inventory|hud|ui|interface|menu|minimap|tooltips?|hotkeys?|stack|stacking|sorting|auto|reloader|pause|damage ?numbers|hit ?numbers|indicators?|compass|quick"],
  ["gameplay", "overhaul|rebalance|balance|realism|realistic|hardcore|difficulty|mechanics|gameplay|survival|levels?|leveling|skills?|classes|magic|spells?|quests?|events?|story|progression|expansion"],
];
/** 3. broad source buckets that still say "adds content to the game". */
const FALLBACK: Record<string, TaxKey> = { content: "gameplay", addon: "gameplay", mod: "gameplay", mods: "gameplay" };

const DIRECT_OF: Record<string, TaxKey> = {};
for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) for (const c of cats) DIRECT_OF[c] = k;
const JS_RULES = RULES.map(([k, re]) => [k, new RegExp(`\\b(${re})\\b`, "i")] as const);

/** The category of one mod (JS), exactly as classifySql() computes it in SQL. */
export function classify(m: { category: string; name: string; description: string | null }): TaxKey | "other" {
  const c = m.category.trim().toLowerCase();
  if (DIRECT_OF[c]) return DIRECT_OF[c];
  for (const [k, re] of JS_RULES) if (re.test(m.name)) return k;
  const d = (m.description ?? "").slice(0, 400);
  for (const [k, re] of JS_RULES) if (re.test(d)) return k;
  return FALLBACK[c] ?? "other";
}
export const taxOf = (m: { category: string; name: string; description: string | null }) => {
  const k = classify(m);
  return k === "other" ? null : TAX[k];
};

/** The same classification as a SQL CASE expression over "GameMod". */
function classifySql(): Prisma.Sql {
  const cat = Prisma.sql`lower(btrim("category"))`;
  const whens: Prisma.Sql[] = [];
  for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) whens.push(Prisma.sql`WHEN ${cat} IN (${Prisma.join(cats)}) THEN ${k}`);
  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN "name" ~* ${`\\m(${re})\\M`} THEN ${k}`);
  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN left(coalesce("description", ''), 400) ~* ${`\\m(${re})\\M`} THEN ${k}`);
  for (const [c, k] of Object.entries(FALLBACK)) whens.push(Prisma.sql`WHEN ${cat} = ${c} THEN ${k}`);
  return Prisma.sql`(CASE ${Prisma.join(whens, " ")} ELSE 'other' END)`;
}

// ── counts (DB-wide, cached like lib/mods-catalog's aggregates) ────────────
export const taxonomyCounts = unstable_cache(
  async (): Promise<{ family: string; key: string; count: number }[]> => {
    const rows = await db.$queryRaw<{ f: string; k: string; c: bigint }[]>(Prisma.sql`
      SELECT "gameFamily" AS f, ${classifySql()} AS k, COUNT(*) AS c FROM "GameMod"
      WHERE "active" = true AND "upstreamOk" = true GROUP BY 1, 2`);
    return rows.map((r) => ({ family: r.f, key: r.k, count: Number(r.c) }));
  },
  ["nxm:taxonomyCounts:v1"],
  { revalidate: 600 },
);

/** Categories with their real counts, for one family or every game, largest first ("other" excluded). */
export async function categoryCounts(family?: string): Promise<{ cat: TaxCat; count: number }[]> {
  const rows = await taxonomyCounts();
  const by = new Map<string, number>();
  for (const r of rows) if (!family || r.family === family) by.set(r.key, (by.get(r.key) ?? 0) + r.count);
  return TAXONOMY.filter((t) => (by.get(t.key) ?? 0) > 0).map((t) => ({ cat: t, count: by.get(t.key)! })).sort((a, b) => b.count - a.count);
}

/** Share of public mods in a real category (not "other"), for a family or overall. */
export async function coverage(family?: string) {
  const rows = (await taxonomyCounts()).filter((r) => !family || r.family === family);
  const total = rows.reduce((s, r) => s + r.count, 0);
  const other = rows.filter((r) => r.key === "other").reduce((s, r) => s + r.count, 0);
  return { total, categorized: total - other, pct: total ? (total - other) / total : 0 };
}

// ── querying by category (search + sort + pagination) ─────────────────────
export type TaxSort = "downloads" | "latest" | "featured";
const ORDER: Record<TaxSort, Prisma.Sql> = {
  downloads: Prisma.sql`"downloads" DESC NULLS LAST, "name" ASC`,
  latest: Prisma.sql`"createdAt" DESC`,
  featured: Prisma.sql`"featured" DESC, "downloads" DESC NULLS LAST, "name" ASC`,
};

export type ModCard = ModSummary & { banner: string | null };

function toCard(m: GameMod, agg?: { avg: number | null; count: number }): ModCard {
  return {
    id: m.id, gameFamily: m.gameFamily, gameFamilyLabel: GAME_DISPLAY[m.gameFamily as GameFamily]?.name ?? m.gameFamily,
    name: m.name, slug: m.slug, category: m.category, source: m.source, iconUrl: m.iconUrl, description: m.description,
    downloads: m.downloads, featured: m.featured, paid: m.paid, verified: m.verifiedAt !== null, impact: m.impact,
    createdAt: m.createdAt.toISOString(), avgRating: agg?.avg ?? null, ratingCount: agg?.count ?? 0,
    url: m.url, sourceId: m.sourceId, appliesToVariant: m.appliesToVariant,
    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    banner: m.galleryUrls[0] ?? null,
  };
}

/** Public mods in one taxonomy category (optionally one family and a search), real total + page. */
export async function queryByCategory(opts: { key: TaxKey; family?: string; q?: string; sort?: TaxSort; page?: number; perPage?: number }) {
  const per = opts.perPage ?? 12;
  const q = (opts.q ?? "").trim();
  const conds: Prisma.Sql[] = [Prisma.sql`"active" = true`, Prisma.sql`"upstreamOk" = true`, Prisma.sql`${classifySql()} = ${opts.key}`];
  if (opts.family) conds.push(Prisma.sql`"gameFamily" = ${opts.family}`);
  if (q) {
    const like = `%${q.replace(/[\\%_]/g, (c) => `\\${c}`)}%`;
    conds.push(Prisma.sql`("name" ILIKE ${like} OR "category" ILIKE ${like} OR "description" ILIKE ${like})`);
  }
  const where = Prisma.join(conds, " AND ");
  const [{ c }] = await db.$queryRaw<{ c: bigint }[]>(Prisma.sql`SELECT COUNT(*) AS c FROM "GameMod" WHERE ${where}`);
  const total = Number(c);
  const pages = Math.max(1, Math.ceil(total / per));
  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), pages);
  const ids = await db.$queryRaw<{ id: string }[]>(Prisma.sql`
    SELECT "id" FROM "GameMod" WHERE ${where} ORDER BY ${ORDER[opts.sort ?? "downloads"]} LIMIT ${per} OFFSET ${(page - 1) * per}`);
  const mods = await cardsByIds(ids.map((r) => r.id));
  return { mods, total, page, totalPages: pages, perPage: per };
}

/** Top mods per category in one query (window function), cached per family. */
export const topPerCategory = unstable_cache(
  async (family: string | null, take: number): Promise<Record<string, string[]>> => {
    const fam = family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty;
    const rows = await db.$queryRaw<{ id: string; k: string }[]>(Prisma.sql`
      SELECT id, k FROM (
        SELECT id, k, row_number() OVER (PARTITION BY k ORDER BY "downloads" DESC NULLS LAST, "name" ASC) AS rn FROM (
          SELECT "id", "downloads", "name", ${classifySql()} AS k FROM "GameMod"
          WHERE "active" = true AND "upstreamOk" = true ${fam}) t) x
      WHERE rn <= ${take}`);
    const out: Record<string, string[]> = {};
    for (const r of rows) (out[r.k] ??= []).push(r.id);
    return out;
  },
  ["nxm:topPerCategory:v1"],
  { revalidate: 600 },
);

/** Full cards (with the first gallery image as banner) for ids, in the given order. */
export async function cardsByIds(ids: string[]): Promise<ModCard[]> {
  if (!ids.length) return [];
  const rows = await db.gameMod.findMany({ where: { id: { in: ids }, active: true, upstreamOk: true } });
  const aggs = await db.modRating.groupBy({ by: ["gameModId"], where: { gameModId: { in: ids } }, _avg: { rating: true }, _count: { rating: true } });
  const agg = new Map(aggs.map((a) => [a.gameModId, { avg: a._avg.rating, count: a._count.rating }]));
  const byId = new Map(rows.map((r) => [r.id, toCard(r, agg.get(r.id))]));
  return ids.map((id) => byId.get(id)).filter((x): x is ModCard => !!x);
}

/** Adds each mod's first real gallery image (GameMod.galleryUrls[0]) as its card banner. */
export async function withBanners<T extends ModSummary>(mods: T[]): Promise<(T & { banner: string | null })[]> {
  if (!mods.length) return [];
  const rows = await db.gameMod.findMany({ where: { id: { in: mods.map((m) => m.id) } }, select: { id: true, galleryUrls: true } });
  const g = new Map(rows.map((r) => [r.id, r.galleryUrls[0] ?? null]));
  return mods.map((m) => ({ ...m, banner: g.get(m.id) ?? null }));
}

