/** Tile illustration: the design's animated CSS kinds, else the category's card art on its gradient. */
function ill(kind: string | undefined, card: string) {
  if (kind === "tick") return `<div class="ti ti-tick">${"<i></i>".repeat(16)}</div>`;
  if (kind === "nodes") return `<div class="ti ti-nodes"><i></i><i></i><i></i><i></i><b></b></div>`;
  if (kind === "terrain") return `<div class="ti ti-terrain"><i></i><i></i><i></i></div>`;
  if (kind === "path") return `<div class="ti ti-path"><i></i><i></i><i></i></div>`;
  if (kind === "gear") return `<div class="ti ti-gear"><i></i><i></i></div>`;
  return `<div class="ti" style="background:linear-gradient(135deg,var(--c1),var(--c2));overflow:hidden"><svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%;display:block" aria-hidden="true">${CARD_ILL[card] ?? CARD_ILL.core}</svg></div>`;
}

/** The "What kind of mod it is" tile: the mod's NxLabs category, with its source category stated. */
export function tagTile(m: { category: string; name: string; description: string | null; source: string }) {
  const t = taxOf(m);
  const src = `Listed on ${sourceLabel(m.source)} as “${m.category}”`;
  if (t) return `<article class="tt" style="--c1:${t.c1};--c2:${t.c2}">${ill(t.ill, t.card)}<div><span class="tt-k">${esc(src)}</span><h3>${esc(t.label)}</h3><p>${esc(t.desc)}</p></div></article>`;
  return `<article class="tt" style="--c1:#6F8DFF;--c2:#9B6BFF">${ill("nodes", "core")}<div><span class="tt-k">${esc(src)}</span><h3>${esc(m.category)}</h3><p>Its source category doesn’t say more about what it does, so NxLabs lists it under Other.</p></div></article>`;
}
/** A category tile's own illustration (hub + per-game "Browse by what you need"). */
export const catIll = (t: TaxCat) => ill(t.ill, t.card);

/** Real icon when the source published one, else the design's monogram letter(s). */
export function iconOr(m: { name: string; iconUrl: string | null }, letters = 1) {
  const initial = esc(m.name.slice(0, letters));
  // a dead upstream icon falls back to the same monogram, never a broken image
  return m.iconUrl
    ? `<img src="${attr(m.iconUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-m="${initial}" style="width:100%;height:100%;object-fit:cover;border-radius:inherit" onerror="this.parentNode.textContent=this.dataset.m">`
    : initial;
}

/** The mod's own lead image (first real gallery screenshot) over the category art; a dead
 *  image removes itself so the category illustration shows through. */
const banner = (url: string | null | undefined, radius: string) =>
  url
    ? `<img class="nxm-banner" src="${attr(url)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:${radius}" onerror="this.remove()">`
    : "";

