      "fresh:html": railHtml("fresh", "fr-title", "Recently updated", "Real last-shipped times from each source.",
        browseHref(f.family, { sort: "latest" }), `Recently updated ${f.label} mods`, fresh,
        (m, i) => xmodCard(m, `n${i}`, `<span class="mc-new">Updated ${ago(m.upstreamUpdatedAt)}</span>`), ' style="padding-top:0"'),
      "cats:html": await catsHtml(f, cats),
      "plans:html": plansHtml(f, plans, inst),
      "faq.install": inst
