// all read it, so they always agree with each other.
type Row = { id: string; f: string; k: string; d: number | null; c: number; ft: boolean; n: string };
const TTL = 10 * 60 * 1000;
const g = globalThis as unknown as { __nxmTaxIdx?: { at: number; rows: Row[] }; __nxmTaxBuild?: Promise<Row[]> };
async function build(): Promise<Row[]> {
  const rows = await db.$queryRaw<{ id: string; f: string; k: string; d: number | null; c: Date; ft: boolean; n: string }[]>(Prisma.sql`
    SELECT "id", "gameFamily" AS f, ${classifySql()} AS k, "downloads" AS d, "createdAt" AS c, "featured" AS ft, "name" AS n
    FROM "GameMod" WHERE "active" = true AND "upstreamOk" = true`);
  const out = rows.map((r) => ({ id: r.id, f: r.f, k: r.k, d: r.d, c: r.c.getTime(), ft: r.ft, n: r.n }));
  g.__nxmTaxIdx = { at: Date.now(), rows: out };
  return out;
}
async function index(): Promise<Row[]> {
  const cur = g.__nxmTaxIdx;
  if (cur && Date.now() - cur.at < TTL) return cur.rows;
  const pending = (g.__nxmTaxBuild ??= build().finally(() => { g.__nxmTaxBuild = undefined; }));
  return cur ? cur.rows : pending; // stale-while-revalidate once warm
}

export type TaxSort = "downloads" | "latest" | "featured";
const byDl = (a: Row, b: Row) => (b.d ?? -1) - (a.d ?? -1) || a.n.localeCompare(b.n);
const CMP: Record<TaxSort, (a: Row, b: Row) => number> = {
  downloads: byDl,
  latest: (a, b) => b.c - a.c,
  featured: (a, b) => Number(b.ft) - Number(a.ft) || byDl(a, b),
};

/** Categories with their real counts, for one family or every game, largest first ("other" excluded). */
export async function categoryCounts(family?: string): Promise<{ cat: TaxCat; count: number }[]> {
  const by = new Map<string, number>();
  for (const r of await index()) if (!family || r.f === family) by.set(r.k, (by.get(r.k) ?? 0) + 1);
  return TAXONOMY.filter((t) => (by.get(t.key) ?? 0) > 0).map((t) => ({ cat: t, count: by.get(t.key)! })).sort((a, b) => b.count - a.count);
}

/** Share of public mods in a real category (not "other"), for a family or overall. */
export async function coverage(family?: string) {
  const rows = (await index()).filter((r) => !family || r.f === family);
  const other = rows.filter((r) => r.k === "other").length;
  return { total: rows.length, categorized: rows.length - other, pct: rows.length ? (rows.length - other) / rows.length : 0 };
}

/** The most-downloaded mod ids per category (one family, or every game with null). */
export async function topPerCategory(family: string | null, take: number): Promise<Record<string, string[]>> {
  const out: Record<string, Row[]> = {};
  for (const r of await index()) if (!family || r.f === family) (out[r.k] ??= []).push(r);
  return Object.fromEntries(Object.entries(out).map(([k, rs]) => [k, rs.sort(byDl).slice(0, take).map((r) => r.id)]));
}

/** Ids of public mods matching a search (the same fields queryCatalogMods searches). */
async function searchIds(q: string, family?: string): Promise<Set<string>> {
  const like = `%${q.replace(/[\\%_]/g, (c) => `\\${c}`)}%`;
  const rows = await db.$queryRaw<{ id: string }[]>(Prisma.sql`
    SELECT "id" FROM "GameMod" WHERE "active" = true AND "upstreamOk" = true
    ${family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty}
    AND ("name" ILIKE ${like} OR "category" ILIKE ${like} OR "description" ILIKE ${like})`);
  return new Set(rows.map((r) => r.id));
}

/**
 * Public mods — optionally one category, one family and a search — with a real
 * total and page. Same public filter and search fields as queryCatalogMods;
 * download sorts put mods without a count LAST (queryCatalogMods' Postgres
 * default puts them first).
 */
export async function queryMods(opts: { key?: TaxKey; family?: string; q?: string; sort?: TaxSort; page?: number; perPage?: number }) {
  const per = opts.perPage ?? 12;
  const q = (opts.q ?? "").trim();
  const hits = q ? await searchIds(q, opts.family) : null;
  const rows = (await index()).filter((r) => (!opts.family || r.f === opts.family) && (!opts.key || r.k === opts.key) && (!hits || hits.has(r.id)));
  const total = rows.length;
  const pages = Math.max(1, Math.ceil(total / per));
  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), pages);
  const ids = rows.sort(CMP[opts.sort ?? "downloads"]).slice((page - 1) * per, page * per).map((r) => r.id);
  return { mods: await cardsByIds(ids), total, page, totalPages: pages, perPage: per };
}

/** Real per-game match counts for a category and/or search, in one pass. */
export async function countsByFamily(opts: { key?: TaxKey; q?: string }): Promise<Map<string, number>> {
  const q = (opts.q ?? "").trim();
  const hits = q ? await searchIds(q) : null;
  const out = new Map<string, number>();
  for (const r of await index()) if ((!opts.key || r.k === opts.key) && (!hits || hits.has(r.id))) out.set(r.f, (out.get(r.f) ?? 0) + 1);
  return out;
}

// ── cards ──────────────────────────────────────────────────────────────────
export type ModCard = ModSummary & { banner: string | null };

function toCard(m: GameMod, agg?: { avg: number | null; count: number }): ModCard {
  return {
    id: m.id, gameFamily: m.gameFamily, gameFamilyLabel: GAME_DISPLAY[m.gameFamily as GameFamily]?.name ?? m.gameFamily,
    name: m.name, slug: m.slug, category: m.category, source: m.source, iconUrl: m.iconUrl, description: m.description,
    downloads: m.downloads, featured: m.featured, paid: m.paid, verified: m.verifiedAt !== null, impact: m.impact,
    createdAt: m.createdAt.toISOString(), avgRating: agg?.avg ?? null, ratingCount: agg?.count ?? 0,
    url: m.url, sourceId: m.sourceId, appliesToVariant: m.appliesToVariant,
    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    banner: m.galleryUrls[0] ?? null,
  };
}

/** Full cards (with the first gallery image as banner) for ids, in the given order. */
export async function cardsByIds(ids: string[]): Promise<ModCard[]> {
  if (!ids.length) return [];
  const rows = await db.gameMod.findMany({ where: { id: { in: ids }, active: true, upstreamOk: true } });
  const aggs = await db.modRating.groupBy({ by: ["gameModId"], where: { gameModId: { in: ids } }, _avg: { rating: true }, _count: { rating: true } });
  const agg = new Map(aggs.map((a) => [a.gameModId, { avg: a._avg.rating, count: a._count.rating }]));
  const byId = new Map(rows.map((r) => [r.id, toCard(r, agg.get(r.id))]));
  return ids.map((id) => byId.get(id)).filter((x): x is ModCard => !!x);
}

/** Adds each mod's first real gallery image (GameMod.galleryUrls[0]) as its card banner. */
export async function withBanners<T extends ModSummary>(mods: T[]): Promise<(T & { banner: string | null })[]> {
  if (!mods.length) return [];
  const rows = await db.gameMod.findMany({ where: { id: { in: mods.map((m) => m.id) } }, select: { id: true, galleryUrls: true } });
  const gal = new Map(rows.map((r) => [r.id, r.galleryUrls[0] ?? null]));
  return mods.map((m) => ({ ...m, banner: gal.get(m.id) ?? null }));
}
